<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'
import { api, clearSession, normalizeUser, uploadFile } from './api.js'
import { demoComments, demoPosts } from './demo.js'

const tabs=[['recommended','推荐'],['latest','最新'],['global','全局']]
const categoryTabs=[['recommended','热门'],['latest','最新']]
const tab=ref('recommended'), posts=ref([]), status=ref('loading'), error=ref(''), demoMode=ref(false)
const viewer=ref(null), loginOpen=ref(false), composerOpen=ref(false), detail=ref(null), comments=ref([])
const draft=ref(localStorage.getItem('fanbbs_draft')||''), busy=ref(false), toast=ref(''), query=ref(''), loginError=ref('')
const selectedFiles=ref([]), composerCategories=ref([]), composerTags=ref([])
const composeFields=ref({title:'',summary:'',kind:'article',categoryId:'',tagIds:[],visibility:'public'})
const postEditor=ref(null), postEditFields=ref({title:'',summary:'',content:'',categoryId:'',tagIds:[],visibility:'public'})
const recoveryCodes=ref([])
const accountBusy=ref(false), accountError=ref(''), replyingTo=ref(null)
const postRevisions=ref([]), activity=ref([])
const view=ref('home'), authMode=ref('login'), categories=ref([]), results=ref([]), resultUsers=ref([]), resultTags=ref([]), bookmarks=ref([]), notifications=ref([]), adminQueue=ref([]), sectionError=ref(''), detailOrigin=ref('#home')
const messageMode=ref('notifications'), conversations=ref([]), activeConversation=ref(null), messages=ref([])
const conversationCursor=ref(''), messageCursor=ref(''), eventCursor=ref('');let eventTimer
const feedCursor=ref(''), commentCursor=ref(''), bookmarkCursor=ref(''), notificationCursor=ref(''), pageBusy=ref(false)
let feedGeneration=0, sectionGeneration=0
const adminMode=ref('reports'), adminUsers=ref([]), adminContent=ref([]), adminTaxonomy=ref({categories:[],tags:[]})
const adminContentFilter=ref({status:'published',type:'',q:''})
const adminUserFilter=ref({status:'',role:'',q:''})
const publicProfile=ref(null), socialList=ref([]), deviceSessions=ref([]), feedFilters=ref({})
const activeCategory=ref(null)
const publicContentTab=ref('posts'), publicPosts=ref([]), publicComments=ref([]), publicContentCursor=ref('')
const blockedUsers=ref([]), followedCategories=ref([]), blockCursor=ref(''), categoryFollowCursor=ref('')
const homepage=ref({carousel:[],announcements:[]}), homepageAdmin=ref(null)
const productTypes=ref([]), products=ref([]), cart=ref([]), orders=ref([]), selectedProduct=ref(null), selectedOrder=ref(null), productTypeFilter=ref('')
const collections=ref([]), publicCollections=ref([]), openedCollection=ref(null), collectionCursor=ref('')
const shippingAddresses=ref([]), selectedAddressId=ref('')
const game=ref(null), pointEvents=ref([]), tasks=ref([]), ranks=ref([]), frames=ref([])
const adminCommerce=ref({types:[],products:[],orders:[]}), adminOrderFilter=ref(''), selectedAdminOrder=ref(null)
const adminTypeEditing=ref(''), adminTypeForm=ref({slug:'',name:'',status:'active',reason:''})
const adminCategoryEditing=ref(''), adminCategoryForm=ref({slug:'',name:'',description:'',image_url:'',background_url:''})
const adminProductEditing=ref(''), adminProductForm=ref({type_id:'',sku:'',name:'',description:'',inventory:0,status:'draft',reason:''})
const pendingPosts=new Set()
const visiblePosts=computed(()=>posts.value.filter(p=>`${p.author.name} ${p.author.handle} ${p.content}`.toLowerCase().includes(query.value.toLowerCase())))
function mergeUnique(current,incoming){const seen=new Set(current.map(x=>x.id));return current.concat((incoming||[]).filter(x=>x?.id&&!seen.has(x.id)&&seen.add(x.id)))}

function announce(message){ toast.value=message; setTimeout(()=>{if(toast.value===message)toast.value=''},2600) }
async function loadFeed(){ const generation=++feedGeneration;status.value='loading'; error.value='';feedCursor.value=''; try { const r=await api.feed(tab.value,feedFilters.value);if(generation!==feedGeneration)return; posts.value=r.data||[];feedCursor.value=r.page?.next_cursor||''; demoMode.value=false;status.value=posts.value.length?'ready':'empty' } catch(e){if(generation!==feedGeneration)return;error.value=e.message;if(e.code==='network_error'){posts.value=demoPosts.map(p=>({...p}));demoMode.value=true;status.value='ready'}else{posts.value=[];demoMode.value=false;status.value='error'}} }
async function loadMoreFeed(){if(!feedCursor.value||pageBusy.value)return;const generation=feedGeneration,cursor=feedCursor.value;pageBusy.value=true;try{const r=await api.feed(tab.value,feedFilters.value,cursor);if(generation!==feedGeneration)return;posts.value=mergeUnique(posts.value,r.data);feedCursor.value=r.page?.next_cursor||''}catch(e){announce(e.message)}finally{pageBusy.value=false}}
async function changeTab(value){ tab.value=value; await loadFeed() }
async function navigate(target){ const generation=++sectionGeneration,resetCategory=target==='home'&&!!activeCategory.value;detail.value=null;if(target==='home'){activeCategory.value=null;feedFilters.value={}}view.value=target;sectionError.value='';history.replaceState({},'',`#${target}`);try{if(target==='home'&&resetCategory)await loadFeed();if(target==='discover'){categories.value=(await api.categories()).data||[]}if(target==='saved'){const [saved,curated]=await Promise.all([api.bookmarks(),api.collections()]);if(generation!==sectionGeneration)return;bookmarks.value=saved.data||[];bookmarkCursor.value=saved.page?.next_cursor||'';collections.value=curated.data||[];collectionCursor.value=curated.page?.next_cursor||''}if(target==='messages'){messageMode.value='notifications';const r=await api.notifications();if(generation!==sectionGeneration)return;notifications.value=r.data||[];notificationCursor.value=r.page?.next_cursor||''}if(target==='me'){const [sessions,blocks,categoryFollows,curated,addresses]=await Promise.all([api.sessions(),api.blocks(),api.categoryFollows(),api.collections(),api.shippingAddresses()]);if(generation!==sectionGeneration)return;deviceSessions.value=sessions.data||[];blockedUsers.value=blocks.data||[];blockCursor.value=blocks.page?.next_cursor||'';followedCategories.value=categoryFollows.data||[];categoryFollowCursor.value=categoryFollows.page?.next_cursor||'';collections.value=curated.data||[];collectionCursor.value=curated.page?.next_cursor||'';shippingAddresses.value=addresses.data||[];selectedAddressId.value=addresses.data?.find(a=>a.is_default)?.id||addresses.data?.[0]?.id||''}if(target==='admin')adminQueue.value=(await api.adminReview()).data||[]}catch(e){if(generation===sectionGeneration)sectionError.value=e.message} }
async function loadMoreBookmarks(){if(!bookmarkCursor.value||pageBusy.value)return;pageBusy.value=true;const generation=sectionGeneration;try{const r=await api.bookmarks(bookmarkCursor.value);if(generation!==sectionGeneration)return;bookmarks.value=mergeUnique(bookmarks.value,r.data);bookmarkCursor.value=r.page?.next_cursor||''}catch(e){sectionError.value=e.message}finally{pageBusy.value=false}}
async function loadMoreNotifications(){if(!notificationCursor.value||pageBusy.value)return;pageBusy.value=true;const generation=sectionGeneration;try{const r=await api.notifications(notificationCursor.value);if(generation!==sectionGeneration)return;notifications.value=mergeUnique(notifications.value,r.data);notificationCursor.value=r.page?.next_cursor||''}catch(e){sectionError.value=e.message}finally{pageBusy.value=false}}
function requireAuth(action){ if(!viewer.value){loginOpen.value=true; nextTick(()=>document.querySelector('#identity')?.focus()); return false} action(); return true }
function openComposer(){requireAuth(async()=>{composerOpen.value=true;error.value='';try{const [categoryResult,tagResult]=await Promise.all([api.categories(),api.tags()]);composerCategories.value=categoryResult.data||[];composerTags.value=tagResult.data||[]}catch(e){error.value=e.message}})}
function storeSession(data){sessionStorage.setItem('fanbbs_access_token',data.access_token);if(data.refresh_token)sessionStorage.setItem('fanbbs_refresh_token',data.refresh_token);viewer.value=normalizeUser(data.user);sessionStorage.setItem('fanbbs_user',JSON.stringify(viewer.value))}
async function doLogin(e){ busy.value=true;loginError.value=''; const f=new FormData(e.currentTarget); try{const r=await api.login(f.get('identity'),f.get('password'));storeSession(r.data);loginOpen.value=false;announce('登录成功')}catch(err){if(err.code==='network_error'&&demoMode.value&&f.get('identity')&&f.get('password')){viewer.value={name:'旅行者',handle:'traveler'};loginOpen.value=false;announce('已进入本地预览模式')}else loginError.value=err.message}finally{busy.value=false}}
async function doRegister(e){busy.value=true;loginError.value='';const f=new FormData(e.currentTarget);try{const r=await api.register(f.get('handle'),f.get('email'),f.get('display_name'),f.get('password'));storeSession(r.data);recoveryCodes.value=r.data.recovery_codes||[];authMode.value='codes';announce('账号创建成功，请保存恢复码')}catch(err){loginError.value=err.message}finally{busy.value=false}}
async function doRecover(e){busy.value=true;loginError.value='';const f=new FormData(e.currentTarget);try{const r=await api.recover(f.get('account'),f.get('recovery_code'),f.get('new_password'));recoveryCodes.value=r.data.recovery_codes||[];authMode.value='codes';announce('密码已重置，其他会话已撤销')}catch(err){loginError.value=err.message}finally{busy.value=false}}
function finishRecoveryCodes(){recoveryCodes.value=[];loginOpen.value=false;authMode.value='login'}
async function rotateCodes(){const password=prompt('请输入当前密码');if(!password)return;try{recoveryCodes.value=(await api.rotateRecoveryCodes(password)).data.recovery_codes||[];authMode.value='codes';loginOpen.value=true}catch(e){announce(e.message)}}
async function logout(){try{await api.logout()}catch{}clearSession();viewer.value=null;navigate('home');announce('已退出登录')}
function closeDialog(kind){ if(kind==='compose'&&(draft.value.trim()||composeFields.value.title.trim()||composeFields.value.summary.trim())&&!confirm('草稿尚未发布，确定关闭吗？'))return; loginOpen.value=false;composerOpen.value=false }
function selectMedia(e){selectedFiles.value=Array.from(e.target.files||[]).slice(0,8)}
function saveDraft(){localStorage.setItem('fanbbs_draft',draft.value)}
async function publish(){if(!draft.value.trim())return;busy.value=true;error.value='';const uploadedMediaIds=[];try{let p;const fields=composeFields.value;const input={content:draft.value.trim(),kind:fields.kind,visibility:fields.visibility,tag_ids:[...fields.tagIds],media_ids:uploadedMediaIds};if(fields.title.trim())input.title=fields.title.trim();if(fields.summary.trim())input.summary=fields.summary.trim();if(fields.categoryId)input.category_id=fields.categoryId;if(demoMode.value)p={...demoPosts[0],id:`local-${Date.now()}`,title:input.title||'',summary:input.summary||'',kind:input.kind,visibility:input.visibility,content:input.content,author:viewer.value,age:'刚刚',comments:0,reposts:0,likes:0,views:0,avatar:'旅'};else{for(const file of selectedFiles.value)uploadedMediaIds.push((await uploadFile(file,{altText:file.name})).data.id);p=(await api.createPost(input)).data}posts.value.unshift(p);draft.value='';selectedFiles.value=[];composeFields.value={title:'',summary:'',kind:'article',categoryId:'',tagIds:[],visibility:'public'};localStorage.removeItem('fanbbs_draft');composerOpen.value=false;announce('帖子已发布')}catch(e){await Promise.allSettled(uploadedMediaIds.map(id=>api.abandonMedia(id)));error.value=e.message}finally{busy.value=false}}
async function toggleLike(post){requireAuth(async()=>{const key=`like:${post.id}`;if(pendingPosts.has(key))return;pendingPosts.add(key);const was=post.liked;post.liked=!was;post.likes+=was?-1:1;try{if(!demoMode.value){const r=await api.like(post.id,was);post.liked=r.data.liked;post.likes=r.data.like_count}}catch(e){post.liked=was;post.likes+=was?1:-1;announce(e.message)}finally{pendingPosts.delete(key)}})}
async function repost(post){requireAuth(async()=>{const key=`repost:${post.id}`;if(pendingPosts.has(key))return;pendingPosts.add(key);const was=!!post.reposted;try{await api.repost(post.id,was);post.reposted=!was;post.reposts=Math.max(0,(post.reposts||0)+(was?-1:1));announce(was?'已取消转发':'已转发')}catch(e){announce(e.message)}finally{pendingPosts.delete(key)}})}
async function loadDetail(id,fallback=null){const generation=++sectionGeneration;status.value='loading';detail.value=fallback?.author?fallback:null;comments.value=[];commentCursor.value='';try{if(!demoMode.value)detail.value=(await api.detail(id)).data;else detail.value=fallback||demoPosts.find(p=>p.id===id);if(!detail.value)throw new Error('帖子不存在');const r=demoMode.value?{data:demoComments,page:{}}:await api.comments(id);if(generation!==sectionGeneration)return;comments.value=r.data||[];commentCursor.value=r.page?.next_cursor||'';status.value='ready'}catch(e){if(generation!==sectionGeneration)return;detail.value=null;status.value='error';error.value=e.message}nextTick(()=>document.querySelector('.detail-title')?.focus())}
async function loadMoreComments(){if(!commentCursor.value||pageBusy.value||!detail.value)return;pageBusy.value=true;const generation=sectionGeneration,id=detail.value.id;try{const r=await api.comments(id,commentCursor.value);if(generation!==sectionGeneration||detail.value?.id!==id)return;comments.value=mergeUnique(comments.value,r.data);commentCursor.value=r.page?.next_cursor||''}catch(e){announce(e.message)}finally{pageBusy.value=false}}
async function openDetail(post){detailOrigin.value=location.hash&&!location.hash.startsWith('#post-')?location.hash:'#home';window.history.pushState({},'',`#post-${post.id}`);await loadDetail(post.id,post)}
async function closeDetail(){detail.value=null;const target=detailOrigin.value||'#home';history.replaceState({},'',target);if(target.startsWith('#user-')){await openPublicProfile(target.slice(6),false);return}await hydrateRoute(target)}
async function submitComment(e){const f=new FormData(e.currentTarget),content=f.get('comment').trim();if(!content)return;busy.value=true;try{const c=demoMode.value?{id:`local-c-${Date.now()}`,author:viewer.value,content,age:'刚刚',depth:0}:(await api.comment(detail.value.id,content)).data;comments.value.push(c);detail.value.comments++;e.currentTarget.reset();announce('回复已发布')}catch(err){announce(err.message)}finally{busy.value=false}}
function startReply(comment){requireAuth(()=>{replyingTo.value=comment;nextTick(()=>document.getElementById(`reply-${comment.id}`)?.focus())})}
async function submitReply(comment,e){const f=new FormData(e.currentTarget),content=f.get('reply').trim();if(!content)return;busy.value=true;try{const c=demoMode.value?{id:`local-c-${Date.now()}`,parent_id:comment.id,root_id:comment.root_id||comment.id,depth:Math.min(2,(comment.depth||0)+1),author:viewer.value,content,age:'刚刚'}:(await api.reply(detail.value.id,comment.id,content)).data;let index=comments.value.findIndex(item=>item.id===comment.id)+1;while(index<comments.value.length&&(comments.value[index].depth||0)>(comment.depth||0))index++;comments.value.splice(index,0,c);detail.value.comments++;replyingTo.value=null;announce('回复已发布')}catch(err){announce(err.message)}finally{busy.value=false}}
async function runSearch(){if(!query.value.trim())return;view.value='discover';sectionError.value='';try{const r=await api.search(query.value.trim());results.value=r.data.posts||[];resultUsers.value=r.data.users||[];resultTags.value=r.data.tags||[]}catch(e){sectionError.value=e.message}}
function chooseCategory(category){query.value=category.name;runSearch()}
async function toggleBookmark(post){requireAuth(async()=>{const was=!!post.bookmarked;try{await api.bookmark(post.id,was);post.bookmarked=!was;if(was&&view.value==='saved')bookmarks.value=bookmarks.value.filter(p=>p.id!==post.id);announce(was?'已取消收藏':'已收藏')}catch(e){announce(e.message)}})}
async function addPostToCollection(post){requireAuth(async()=>{try{if(!collections.value.length)collections.value=(await api.collections()).data||[];if(!collections.value.length){announce('请先在个人资料中新建收藏集');return}const chosen=prompt(`输入收藏集名称：${collections.value.map(c=>c.name).join('、')}`,collections.value[0].name);if(!chosen)return;const collection=collections.value.find(c=>c.name===chosen.trim());if(!collection){announce('没有找到这个收藏集');return}await api.setCollectionPost(collection.id,post.id);collection.item_count=(collection.item_count||0)+1;announce(`已加入「${collection.name}」`)}catch(e){announce(e.message)}})}
async function createCollection(e){const f=new FormData(e.currentTarget);try{const item=(await api.createCollection({name:f.get('name'),description:f.get('description'),visibility:f.get('visibility')})).data;collections.value.unshift(item);e.currentTarget.reset();announce('收藏集已创建')}catch(err){announce(err.message)}}
async function removeCollection(item){if(!confirm(`删除收藏集「${item.name}」？`))return;try{await api.deleteCollection(item.id);collections.value=collections.value.filter(c=>c.id!==item.id);announce('收藏集已删除')}catch(e){announce(e.message)}}
async function openCollection(item){try{openedCollection.value=(await api.collection(item.id)).data}catch(e){announce(e.message)}}
async function toggleFollow(user){requireAuth(async()=>{try{await api.follow(user.id,!!user.following);user.following=!user.following;announce(user.following?'已关注':'已取消关注')}catch(e){announce(e.message)}})}
async function openPublicProfile(id,push=true){const generation=++sectionGeneration;sectionError.value='';detail.value=null;publicProfile.value=null;socialList.value=[];publicCollections.value=[];view.value='profile';if(push)history.pushState({},'',`#user-${id}`);try{const [profileResult,collectionResult]=await Promise.all([api.profileById(id),api.publicCollections(id)]);if(generation!==sectionGeneration)return;publicProfile.value=profileResult.data;publicCollections.value=collectionResult.data||[];publicContentTab.value='posts';await loadPublicContent('posts',generation)}catch(e){if(generation===sectionGeneration)sectionError.value=e.message}}
async function loadSocial(relation){try{socialList.value=(await api[relation](publicProfile.value.id)).data||[]}catch(e){sectionError.value=e.message}}
async function loadPublicContent(tabName,generation=sectionGeneration){if(!publicProfile.value)return;publicContentTab.value=tabName;publicContentCursor.value='';socialList.value=[];sectionError.value='';try{const r=await api[tabName==='posts'?'profilePosts':'profileComments'](publicProfile.value.id);if(generation!==sectionGeneration)return;if(tabName==='posts')publicPosts.value=r.data||[];else publicComments.value=r.data||[];publicContentCursor.value=r.page?.next_cursor||''}catch(e){if(generation===sectionGeneration)sectionError.value=e.message}}
async function loadMorePublicContent(){if(!publicContentCursor.value||pageBusy.value||!publicProfile.value)return;pageBusy.value=true;const generation=sectionGeneration,tabName=publicContentTab.value;try{const r=await api[tabName==='posts'?'profilePosts':'profileComments'](publicProfile.value.id,publicContentCursor.value);if(generation!==sectionGeneration||tabName!==publicContentTab.value)return;if(tabName==='posts')publicPosts.value=mergeUnique(publicPosts.value,r.data);else publicComments.value=mergeUnique(publicComments.value,r.data);publicContentCursor.value=r.page?.next_cursor||''}catch(e){sectionError.value=e.message}finally{pageBusy.value=false}}
async function openProfileComment(comment){detailOrigin.value=location.hash||`#user-${publicProfile.value.id}`;history.pushState({},'',`#post-${comment.post_id}`);await loadDetail(comment.post_id)}
async function toggleBlockProfile(){requireAuth(async()=>{try{await api.block(publicProfile.value.id,publicProfile.value.blocked_by_me);publicProfile.value.blocked_by_me=!publicProfile.value.blocked_by_me;publicProfile.value.following=false;announce(publicProfile.value.blocked_by_me?'已屏蔽':'已解除屏蔽')}catch(e){announce(e.message)}})}
async function unblockUser(user){try{await api.block(user.id,true);blockedUsers.value=blockedUsers.value.filter(item=>item.id!==user.id);announce('已解除屏蔽')}catch(e){announce(e.message)}}
async function unfollowSavedCategory(item){const category=item.category||item;try{await api.followCategory(category.id,true);followedCategories.value=followedCategories.value.filter(entry=>(entry.category||entry).id!==category.id);const discovered=categories.value.find(entry=>entry.id===category.id);if(discovered)discovered.followed=false;announce('已取消关注分类')}catch(e){announce(e.message)}}
async function loadMoreBlocks(){if(!blockCursor.value||pageBusy.value)return;pageBusy.value=true;try{const r=await api.blocks(blockCursor.value);blockedUsers.value=mergeUnique(blockedUsers.value,r.data);blockCursor.value=r.page?.next_cursor||''}catch(e){sectionError.value=e.message}finally{pageBusy.value=false}}
async function loadMoreCategoryFollows(){if(!categoryFollowCursor.value||pageBusy.value)return;pageBusy.value=true;try{const r=await api.categoryFollows(categoryFollowCursor.value);const known=new Set(followedCategories.value.map(item=>(item.category||item).id));followedCategories.value.push(...(r.data||[]).filter(item=>!known.has((item.category||item).id)));categoryFollowCursor.value=r.page?.next_cursor||''}catch(e){sectionError.value=e.message}finally{pageBusy.value=false}}
async function openCategory(category,push=true){detail.value=null;const known=categories.value.find(item=>item.id===category.id);activeCategory.value={...(known||{}),...category};feedFilters.value={categoryId:category.id};tab.value='recommended';view.value='home';if(push)history.pushState({},'',`#category-${category.id}`);await loadFeed()}
async function changeCategoryTab(value){tab.value=value;await loadFeed()}
async function openTag(tag){feedFilters.value={tagId:tag.id};view.value='home';history.replaceState({},'','#home');await loadFeed()}
async function toggleCategoryFollow(category){requireAuth(async()=>{try{await api.followCategory(category.id,!!category.followed);category.followed=!category.followed;announce(category.followed?'已关注分类':'已取消关注')}catch(e){announce(e.message)}})}
async function revokeDevice(session){if(!confirm('确定撤销这个设备会话吗？'))return;try{await api.revokeSession(session.id);deviceSessions.value=deviceSessions.value.filter(s=>s.id!==session.id);if(session.current){clearSession();viewer.value=null;navigate('home')}announce('设备会话已撤销')}catch(e){announce(e.message)}}
async function messageUser(user){requireAuth(async()=>{try{const conversation=(await api.createConversation(user.id)).data;await navigate('messages');await loadConversations();await openConversation(conversation)}catch(e){announce(e.message)}})}
async function saveProfile(e){const f=new FormData(e.currentTarget);busy.value=true;try{const r=await api.updateProfile({display_name:f.get('display_name'),bio:f.get('bio')});viewer.value=normalizeUser(r.data);sessionStorage.setItem('fanbbs_user',JSON.stringify(viewer.value));announce('资料已保存')}catch(err){sectionError.value=err.message}finally{busy.value=false}}
async function changePassword(e){const form=e.currentTarget,f=new FormData(form),current=f.get('current_password'),replacement=f.get('new_password'),confirmation=f.get('confirm_password');accountError.value='';if(replacement!==confirmation){accountError.value='两次输入的新密码不一致';return}if(!confirm('修改密码后，其他设备上的登录会话将被撤销。确定继续吗？'))return;accountBusy.value=true;try{await api.changePassword(current,replacement);form.reset();announce('密码已修改，其他设备会话已撤销');deviceSessions.value=(await api.sessions()).data||[]}catch(err){accountError.value=err.message}finally{accountBusy.value=false}}
async function deactivateAccount(){accountError.value='';if(!confirm('停用账号后会立即退出，个人资料将不再公开。确定停用吗？'))return;accountBusy.value=true;try{await api.deactivateAccount();clearSession();viewer.value=null;await navigate('home');announce('账号已停用')}catch(err){accountError.value=err.message}finally{accountBusy.value=false}}
function notificationActor(notification){return notification.actor?.display_name||notification.actor?.name||notification.actor?.handle||'社区成员'}
function notificationSubject(notification){const labels={post:'帖子',comment:'回复',user:'用户',message:'私信',report:'举报'};return labels[notification.subject_type]||notification.subject_type||'社区内容'}
function notificationTitle(notification){const actor=notificationActor(notification),subject=notificationSubject(notification);return {comment:`${actor} 回复了你的${subject}`,like:`${actor} 赞了你的${subject}`,repost:`${actor} 转发了你的${subject}`,follow:`${actor} 关注了你`,message:`${actor} 发来私信`,moderation:`${subject}审核结果`}[notification.type]||`${actor}的${notification.type||'社区'}通知`}
function notificationDescription(notification){const payload=notification.payload||{};if(notification.type==='moderation'&&payload.decision)return `${notificationSubject(notification)} · 处理结果：${payload.decision}`;return `${notificationSubject(notification)} · ${notification.type||'通知'}`}
async function openNotification(notification){try{if(!notification.read_at){await api.readNotifications([notification.id]);notification.read_at=new Date().toISOString()}const payload=notification.payload||{};if(notification.type==='message'&&payload.conversation_id){messageMode.value='conversations';const conversation=(await api.conversation(payload.conversation_id)).data;await openConversation(conversation);return}if(notification.subject_type==='user'){await openPublicProfile(notification.subject_id);return}if(notification.subject_type==='post'){await openDetail({id:notification.subject_id});return}if(notification.subject_type==='comment'&&payload.post_id){await openDetail({id:payload.post_id});return}announce(notificationTitle(notification))}catch(e){announce(e.message)}}
async function markAllRead(){try{await api.readNotifications([]);notifications.value.forEach(n=>n.read_at=n.read_at||new Date().toISOString());announce('通知已全部标为已读')}catch(e){announce(e.message)}}
async function loadConversations(){messageMode.value='conversations';activeConversation.value=null;try{const r=await api.conversations();conversations.value=r.data||[];conversationCursor.value=r.page?.next_cursor||'';await pollEvents();clearInterval(eventTimer);eventTimer=setInterval(pollEvents,15000)}catch(e){sectionError.value=e.message}}
async function loadMoreConversations(){if(!conversationCursor.value)return;try{const r=await api.conversations(conversationCursor.value);conversations.value.push(...(r.data||[]));conversationCursor.value=r.page?.next_cursor||''}catch(e){sectionError.value=e.message}}
async function openConversation(item){activeConversation.value=item;try{const [conversation,r]=await Promise.all([api.conversation(item.id),api.messages(item.id)]);activeConversation.value={...item,...conversation.data};messages.value=(r.data||[]).slice().reverse();messageCursor.value=r.page?.next_cursor||'';const latest=messages.value.at(-1);if(latest)await api.markConversationRead(item.id,latest.id)}catch(e){sectionError.value=e.message}}
async function leaveConversation(){if(!confirm('确定离开这个会话吗？'))return;try{await api.leaveConversation(activeConversation.value.id);conversations.value=conversations.value.filter(c=>c.id!==activeConversation.value.id);activeConversation.value=null;messages.value=[];announce('已离开会话')}catch(e){announce(e.message)}}
async function loadOlderMessages(){if(!messageCursor.value)return;try{const r=await api.messages(activeConversation.value.id,messageCursor.value);messages.value.unshift(...(r.data||[]).slice().reverse());messageCursor.value=r.page?.next_cursor||''}catch(e){sectionError.value=e.message}}
async function pollEvents(){try{const r=await api.events(eventCursor.value);eventCursor.value=r.page?.next_cursor||eventCursor.value;const events=r.data||[],createdNotifications=events.filter(event=>event.type==='notification.created'&&event.notification).map(event=>event.notification),messageNotifications=createdNotifications.filter(notification=>notification.type==='message');if(messageMode.value==='notifications'&&createdNotifications.length){const latest=await api.notifications();notifications.value=latest.data||[];notificationCursor.value=latest.page?.next_cursor||''}if(activeConversation.value){const conversationID=activeConversation.value.id;const relevant=messageNotifications.some(notification=>notification.payload?.conversation_id===conversationID);const [conversation,latest]=await Promise.all([api.conversation(conversationID),relevant?api.messages(conversationID):Promise.resolve(null)]);activeConversation.value={...activeConversation.value,...conversation.data};if(latest){messages.value=(latest.data||[]).slice().reverse();messageCursor.value=latest.page?.next_cursor||'';const newest=messages.value.at(-1);if(newest)await api.markConversationRead(conversationID,newest.id)}}}catch(e){if(e.status===401){clearInterval(eventTimer);return}sectionError.value=e.message}}
async function sendMessage(e){const f=new FormData(e.currentTarget),content=f.get('message').trim();if(!content)return;busy.value=true;try{const sent=(await api.sendMessage(activeConversation.value.id,content)).data;messages.value.push(sent);e.currentTarget.reset()}catch(err){sectionError.value=err.message}finally{busy.value=false}}
function messageReadLabel(message){if(message.sender_id!==viewer.value?.id)return '';const sentAt=Date.parse(message.created_at);if(!Number.isFinite(sentAt))return '';const readers=(activeConversation.value?.members||[]).filter(member=>member.user?.id!==viewer.value?.id&&!member.left_at&&Number.isFinite(Date.parse(member.read_at))&&Date.parse(member.read_at)>=sentAt).length;return readers?readers===1?'已读':`${readers} 人已读`:''}
async function moderate(item,decision){const reason=prompt('请填写审核理由');if(!reason)return;try{await api.moderate(item.id,decision,reason);adminQueue.value=adminQueue.value.filter(x=>x.id!==item.id);announce('审核决定已记录')}catch(e){announce(e.message)}}
async function loadAdmin(mode){adminMode.value=mode;sectionError.value='';try{if(mode==='reports')adminQueue.value=(await api.adminReview()).data||[];if(mode==='users')adminUsers.value=(await api.adminUsers(adminUserFilter.value)).data||[];if(mode==='content')adminContent.value=(await api.adminContent(adminContentFilter.value)).data||[];if(mode==='taxonomy'){const [c,t]=await Promise.all([api.categories(),api.tags()]);adminTaxonomy.value={categories:c.data||[],tags:t.data||[]}}if(mode==='commerce'){const [types,productsResult,ordersResult]=await Promise.all([api.adminProductTypes(),api.adminProducts(),api.adminOrders(adminOrderFilter.value)]);adminCommerce.value={types:types.data||[],products:productsResult.data||[],orders:ordersResult.data||[]};if(!adminProductForm.value.type_id&&adminCommerce.value.types[0])adminProductForm.value.type_id=adminCommerce.value.types[0].id}}catch(e){sectionError.value=e.message}}
async function changeUserStatus(user){const status=user.status==='active'?'suspended':'active',reason=prompt(`请填写${status==='active'?'恢复':'停用'}理由`);if(!reason)return;try{await api.setUserStatus(user.id,status,reason);user.status=status;announce('用户状态已更新')}catch(e){announce(e.message)}}
async function decidePendingPost(post,decision){const reason=prompt('请填写审核理由');if(!reason)return;try{post.moderation_state=(await api.moderatePost(post.id,decision,reason)).data.state;announce('文章审核决定已记录')}catch(e){announce(e.message)}}
async function togglePostControl(post,key){const reason=prompt('请填写运营调整理由');if(!reason)return;try{const r=await api.postControls(post.id,{[key]:!post[key],reason});post.pinned=r.data.pinned;post.recommended=r.data.recommended;announce('动态排序控制已更新')}catch(e){announce(e.message)}}
async function loadActivity(){try{activity.value=(await api.activity()).data||[]}catch(e){sectionError.value=e.message}}
async function createTaxonomy(kind){const name=prompt(`新${kind==='category'?'分类':'标签'}名称`);if(!name)return;const slug=prompt('英文 slug');if(!slug)return;try{const r=kind==='category'?await api.createCategory({name,slug}):await api.createTag({name,slug});adminTaxonomy.value[kind==='category'?'categories':'tags'].push(r.data);announce('已创建')}catch(e){announce(e.message)}}
async function editTaxonomy(kind,item){const name=prompt('修改名称',item.name);if(!name)return;const slug=prompt('修改 slug',item.slug);if(!slug)return;try{const r=kind==='category'?await api.updateCategory(item.id,{name,slug}):await api.updateTag(item.id,{name,slug});Object.assign(item,r.data);announce('已更新')}catch(e){announce(e.message)}}
async function removeTaxonomy(kind,item){if(!confirm(`确定删除 ${item.name} 吗？`))return;const reason=prompt('请填写删除理由');if(!reason)return;try{kind==='category'?await api.deleteCategory(item.id,reason):await api.deleteTag(item.id,reason);const key=kind==='category'?'categories':'tags';adminTaxonomy.value[key]=adminTaxonomy.value[key].filter(x=>x.id!==item.id);announce('已删除')}catch(e){announce(e.message)}}
function resetAdminCategory(){adminCategoryEditing.value='';adminCategoryForm.value={slug:'',name:'',description:'',image_url:'',background_url:''}}
function editAdminCategory(item){adminCategoryEditing.value=item.id;adminCategoryForm.value={slug:item.slug,name:item.name,description:item.description||'',image_url:item.image_url||'',background_url:item.background_url||''}}
async function saveAdminCategory(){const input={...adminCategoryForm.value};try{const result=adminCategoryEditing.value?await api.updateCategory(adminCategoryEditing.value,input):await api.createCategory(input);const index=adminTaxonomy.value.categories.findIndex(item=>item.id===result.data.id);if(index<0)adminTaxonomy.value.categories.push(result.data);else adminTaxonomy.value.categories[index]=result.data;resetAdminCategory();announce('分类展示已保存')}catch(e){announce(e.message)}}
async function loadHomepageAdmin(){adminMode.value='homepage';try{homepageAdmin.value=(await api.adminHomepage()).data}catch(e){sectionError.value=e.message}}
async function saveHomepage(e){const f=new FormData(e.currentTarget);try{const payload=JSON.parse(f.get('payload'));homepageAdmin.value=(await api.updateHomepage(homepageAdmin.value.version,{status:f.get('status'),...payload})).data;announce('首页配置已保存')}catch(e){sectionError.value=e.message}}
async function loadShop(typeId=productTypeFilter.value){typeId=typeof typeId==='string'?typeId:productTypeFilter.value;view.value='shop';history.replaceState({},'','#shop');sectionError.value='';productTypeFilter.value=typeId;selectedProduct.value=null;try{const [types,list,basket]=await Promise.all([api.productTypes(),api.products(typeId),viewer.value?api.cart():Promise.resolve({data:[]})]);productTypes.value=types.data||[];products.value=list.data||[];cart.value=basket.data||[]}catch(e){sectionError.value=e.message}}
async function filterProducts(typeId){productTypeFilter.value=typeId;sectionError.value='';selectedProduct.value=null;try{products.value=(await api.products(typeId)).data||[]}catch(e){sectionError.value=e.message}}
async function openProduct(product){try{selectedProduct.value=(await api.product(product.id)).data}catch(e){announce(e.message)}}
async function addCart(product){requireAuth(async()=>{try{const existing=cart.value.find(x=>x.product.id===product.id),quantity=(existing?.quantity||0)+1;const r=await api.setCart(product.id,quantity);if(existing)Object.assign(existing,r.data);else cart.value.push(r.data);announce('已加入清单')}catch(e){announce(e.message)}})}
async function updateCartQuantity(item,change){const quantity=item.quantity+change;if(quantity<1){await removeCartItem(item);return}try{Object.assign(item,(await api.setCart(item.product.id,quantity)).data)}catch(e){announce(e.message)}}
async function removeCartItem(item){try{await api.removeCart(item.product.id);cart.value=cart.value.filter(entry=>entry.product.id!==item.product.id);announce('已从清单移除')}catch(e){announce(e.message)}}
async function checkout(){if(!confirm('这会创建一个不含付款的本地履约订单，继续吗？'))return;try{if(!shippingAddresses.value.length){shippingAddresses.value=(await api.shippingAddresses()).data||[];selectedAddressId.value=shippingAddresses.value.find(a=>a.is_default)?.id||shippingAddresses.value[0]?.id||''}const order=(await api.createOrder(selectedAddressId.value)).data;orders.value.unshift(order);cart.value=[];announce('本地订单已创建，不涉及付款')}catch(e){announce(e.message)}}
async function loadOrders(){view.value='orders';history.replaceState({},'','#orders');sectionError.value='';selectedOrder.value=null;try{const [orderResult,addressResult]=await Promise.all([api.orders(),api.shippingAddresses()]);orders.value=orderResult.data||[];shippingAddresses.value=addressResult.data||[];selectedAddressId.value=shippingAddresses.value.find(a=>a.is_default)?.id||shippingAddresses.value[0]?.id||''}catch(e){sectionError.value=e.message}}
async function openOrder(order){try{selectedOrder.value=(await api.order(order.id)).data}catch(e){announce(e.message)}}
async function cancelOrder(order){const reason=prompt('取消理由');if(!reason)return;try{const updated=(await api.cancelOrder(order.id,reason)).data;Object.assign(order,updated);if(selectedOrder.value?.id===order.id)selectedOrder.value=updated;announce('订单已取消，库存已释放')}catch(e){announce(e.message)}}
async function saveShippingAddress(e){const f=new FormData(e.currentTarget),input={label:f.get('label'),recipient_name:f.get('recipient_name'),phone:f.get('phone'),region:f.get('region'),address_line:f.get('address_line'),postal_code:f.get('postal_code'),is_default:f.get('is_default')==='on'};try{const item=(await api.createShippingAddress(input)).data;await refreshShippingAddresses(item.id);e.currentTarget.reset();announce('收货地址已保存')}catch(err){announce(err.message)}}
async function refreshShippingAddresses(preferred=''){const r=await api.shippingAddresses();shippingAddresses.value=r.data||[];selectedAddressId.value=shippingAddresses.value.some(a=>a.id===preferred)?preferred:shippingAddresses.value.find(a=>a.is_default)?.id||shippingAddresses.value[0]?.id||''}
async function editShippingAddress(item){const recipient=prompt('收件人',item.recipient_name);if(recipient==null)return;const phone=prompt('联系电话',item.phone);if(phone==null)return;const region=prompt('地区',item.region);if(region==null)return;const line=prompt('详细地址',item.address_line);if(line==null)return;const makeDefault=confirm('将这个地址设为默认地址吗？');try{await api.updateShippingAddress(item.id,item.version,{label:item.label,recipient_name:recipient,phone,region,address_line:line,postal_code:item.postal_code||'',is_default:makeDefault||item.is_default});await refreshShippingAddresses(item.id);announce('地址已更新')}catch(e){announce(e.message)}}
async function removeShippingAddress(item){if(!confirm(`删除地址「${item.label||item.recipient_name}」？`))return;try{await api.deleteShippingAddress(item.id);await refreshShippingAddresses();announce('地址已删除')}catch(e){announce(e.message)}}
async function appendTrackingEvent(order){const status=prompt('物流状态：label_created / in_transit / out_for_delivery / delivered / exception','in_transit');if(!status)return;const description=prompt('物流说明','手工更新');if(description==null)return;const location=prompt('地点（可留空）','');if(location==null)return;const reason=prompt('审计理由','人工物流更新');if(!reason)return;try{const event=(await api.addTrackingEvent(order.id,{status:status.trim(),description:description.trim(),location:location.trim(),reason:reason.trim()})).data;order.tracking_events=[...(order.tracking_events||[]),event];announce('物流事件已追加')}catch(e){announce(e.message)}}
async function loadGamification(){view.value='gamification';history.replaceState({},'','#gamification');try{const [g,p,t,r,f]=await Promise.all([api.gamification(),api.pointEvents(),api.tasks(),api.ranks(),api.frames()]);game.value=g.data;pointEvents.value=p.data||[];tasks.value=t.data||[];ranks.value=r.data||[];frames.value=f.data||[]}catch(e){sectionError.value=e.message}}
async function checkIn(){try{await api.checkIn();await loadGamification();announce('今日签到完成')}catch(e){announce(e.message)}}
async function chooseFrame(frame){try{await api.selectFrame(frame.id);frames.value.forEach(f=>f.selected=f.id===frame.id);announce('头像框已选择')}catch(e){announce(e.message)}}
async function clearFrame(){try{await api.selectFrame('');frames.value.forEach(frame=>frame.selected=false);announce('已清除头像框')}catch(e){announce(e.message)}}
function editAdminType(item){adminTypeEditing.value=item.id;adminTypeForm.value={slug:item.slug,name:item.name,status:item.status,reason:''}}
function resetAdminType(){adminTypeEditing.value='';adminTypeForm.value={slug:'',name:'',status:'active',reason:''}}
async function saveAdminType(){const input={...adminTypeForm.value};try{const result=adminTypeEditing.value?await api.updateProductType(adminTypeEditing.value,input):await api.createProductType(input);const index=adminCommerce.value.types.findIndex(item=>item.id===result.data.id);if(index<0)adminCommerce.value.types.push(result.data);else adminCommerce.value.types[index]=result.data;resetAdminType();announce('商品类型已保存')}catch(e){announce(e.message)}}
async function removeAdminType(item){if(!confirm(`确定删除商品类型「${item.name}」吗？`))return;const reason=prompt('请填写删除理由');if(!reason)return;try{await api.deleteProductType(item.id,reason);adminCommerce.value.types=adminCommerce.value.types.filter(entry=>entry.id!==item.id);announce('商品类型已删除')}catch(e){announce(e.message)}}
function editAdminProduct(item){adminProductEditing.value=item.id;adminProductForm.value={type_id:item.type_id,sku:item.sku,name:item.name,description:item.description||'',inventory:item.inventory,status:item.status,reason:''}}
function resetAdminProduct(){adminProductEditing.value='';adminProductForm.value={type_id:adminCommerce.value.types[0]?.id||'',sku:'',name:'',description:'',inventory:0,status:'draft',reason:''}}
async function saveAdminProduct(){const input={...adminProductForm.value,inventory:Number(adminProductForm.value.inventory)};try{const result=adminProductEditing.value?await api.updateProduct(adminProductEditing.value,input):await api.createProduct(input);const index=adminCommerce.value.products.findIndex(item=>item.id===result.data.id);if(index<0)adminCommerce.value.products.push(result.data);else adminCommerce.value.products[index]=result.data;resetAdminProduct();announce('商品已保存')}catch(e){announce(e.message)}}
async function removeAdminProduct(item){if(!confirm(`确定删除商品「${item.name}」吗？已进入订单的商品只能归档。`))return;const reason=prompt('请填写删除理由');if(!reason)return;try{await api.deleteProduct(item.id,reason);adminCommerce.value.products=adminCommerce.value.products.filter(entry=>entry.id!==item.id);announce('商品已删除')}catch(e){announce(e.message)}}
async function openAdminOrder(order){try{selectedAdminOrder.value=(await api.adminOrder(order.id)).data}catch(e){announce(e.message)}}
async function transitionAdminOrder(order,status){const input={status};if(status==='fulfilled'){const carrier=prompt('手工履约方式（仅记录信息，不会联系外部服务）','local');if(carrier==null)return;const tracking=prompt('履约记录编号（可留空）','');if(tracking==null)return;input.fulfillment_carrier=carrier.trim();input.tracking_code=tracking.trim()}const reason=prompt(status==='cancelled'?'请填写管理员取消理由':'请填写手工履约理由');if(!reason)return;input.reason=reason;try{const updated=(await api.transitionOrder(order.id,input)).data;Object.assign(order,updated);if(selectedAdminOrder.value?.id===order.id)selectedAdminOrder.value=updated;announce(status==='cancelled'?'订单已取消':'手工履约状态已记录')}catch(e){announce(e.message)}}
function reportTarget(targetType,targetId){requireAuth(async()=>{const reason=prompt('请说明举报理由（至少 5 个字）');if(reason==null)return;if(reason.trim().length<5){announce('举报理由至少需要 5 个字');return}try{await api.report(targetType,targetId,reason.trim());announce('举报已提交审核')}catch(e){announce(e.message)}})}
function reportPost(post){reportTarget('post',post.id)}
function reportComment(comment){reportTarget('comment',comment.id)}
function reportUser(user){reportTarget('user',user.id)}
async function editPost(post){try{const [categoryResult,tagResult]=await Promise.all([api.categories(),api.tags()]);composerCategories.value=categoryResult.data||[];composerTags.value=tagResult.data||[];postEditor.value=post;postEditFields.value={title:post.title||'',summary:post.summary||'',content:post.content||'',categoryId:post.category?.id||'',tagIds:(post.tags||[]).map(tag=>tag.id),visibility:post.visibility||'public'}}catch(e){announce(e.message)}}
async function savePostEdit(){if(!postEditor.value||!postEditFields.value.content.trim())return;busy.value=true;try{const fields=postEditFields.value,input={title:fields.title.trim(),summary:fields.summary.trim(),content:fields.content.trim(),category_id:fields.categoryId,tag_ids:[...fields.tagIds],visibility:fields.visibility};const updated=(await api.updatePost(postEditor.value.id,postEditor.value.version,input)).data;detail.value=updated;for(const collection of [posts.value,publicPosts.value]){const index=collection.findIndex(post=>post.id===updated.id);if(index>=0)collection[index]=updated}postEditor.value=null;announce('帖子已更新')}catch(e){announce(e.message)}finally{busy.value=false}}
async function deletePost(post){if(!confirm('确定删除这条帖子吗？'))return;try{await api.deletePost(post.id,post.version);posts.value=posts.value.filter(p=>p.id!==post.id);closeDetail();announce('帖子已删除')}catch(e){announce(e.message)}}
async function showRevisions(post){try{postRevisions.value=(await api.postRevisions(post.id)).data||[]}catch(e){announce(e.message)}}
async function editComment(comment){const content=prompt('编辑回复',comment.content);if(content==null||content.trim()===comment.content)return;try{const updated=(await api.updateComment(detail.value.id,comment.id,comment.version,content.trim())).data;const i=comments.value.findIndex(c=>c.id===comment.id);if(i>=0)comments.value[i]=updated;announce('回复已更新')}catch(e){announce(e.message)}}
async function deleteComment(comment){if(!confirm('确定删除这条回复吗？'))return;try{await api.deleteComment(detail.value.id,comment.id,comment.version);if(comments.value.some(c=>c.parent_id===comment.id)){Object.assign(comment,{deleted:true,content:'',body:'',liked:false,like_count:0,author:{name:'已删除',display_name:'已删除',handle:''}})}else comments.value=comments.value.filter(c=>c.id!==comment.id);detail.value.comments=Math.max(0,detail.value.comments-1);announce('回复已删除')}catch(e){announce(e.message)}}
async function toggleCommentLike(comment){const key=`comment-like:${comment.id}`;if(pendingPosts.has(key))return;pendingPosts.add(key);const was=!!comment.liked;try{const r=await api.likeComment(detail.value.id,comment.id,was);comment.liked=r.data.liked;comment.like_count=r.data.like_count}catch(e){announce(e.message)}finally{pendingPosts.delete(key)}}
async function updateAvatar(e){const file=e.target.files?.[0];if(!file)return;busy.value=true;try{const r=await uploadFile(file,{avatar:true,altText:`${viewer.value.name}的头像`});viewer.value.avatar_url=r.data.url;sessionStorage.setItem('fanbbs_user',JSON.stringify(viewer.value));announce('头像已更新')}catch(err){sectionError.value=err.message}finally{busy.value=false;e.target.value=''}}
async function updateCover(e){const file=e.target.files?.[0];if(!file)return;busy.value=true;try{const r=await uploadFile(file,{cover:true,altText:`${viewer.value.name}的主页封面`});viewer.value.cover_url=r.data.url;sessionStorage.setItem('fanbbs_user',JSON.stringify(viewer.value));announce('主页封面已更新')}catch(err){sectionError.value=err.message}finally{busy.value=false;e.target.value=''}}
async function hydrateRoute(hash=location.hash){if(hash.startsWith('#post-')){await loadDetail(hash.slice(6));return}if(hash.startsWith('#user-')){await openPublicProfile(hash.slice(6),false);return}if(hash.startsWith('#category-')){try{const id=hash.slice(10),items=(await api.categories()).data||[];categories.value=items;const category=items.find(item=>item.id===id);if(category){await openCategory(category,false);return}}catch(e){sectionError.value=e.message}}const target=hash.slice(1)||'home';detail.value=null;if(target==='shop'){await loadShop();return}if(target==='orders'){if(viewer.value)await loadOrders();else view.value='home';return}if(target==='gamification'){if(viewer.value)await loadGamification();else view.value='home';return}if(['discover','saved','messages','me','admin'].includes(target)){if(['saved','messages','me','admin'].includes(target)&&!viewer.value){view.value='home';return}await navigate(target);return}activeCategory.value=null;feedFilters.value={};view.value='home';history.replaceState({},'','#home')}
async function syncHistory(){await hydrateRoute(location.hash)}
onMounted(async()=>{try{viewer.value=normalizeUser(JSON.parse(sessionStorage.getItem('fanbbs_user')||'null')||{});if(!viewer.value.handle)viewer.value=null;if(viewer.value){const r=await api.profile();viewer.value=normalizeUser(r.data);sessionStorage.setItem('fanbbs_user',JSON.stringify(viewer.value))}}catch{clearSession();viewer.value=null}try{homepage.value=(await api.homepage()).data.payload||homepage.value}catch{}await loadFeed();await syncHistory();addEventListener('popstate',syncHistory)})
onUnmounted(()=>{removeEventListener('popstate',syncHistory);clearInterval(eventTimer)})
</script>

<template>
  <a class="skip" href="#feed">跳到内容</a>
  <header class="topbar"><button class="icon-button menu" aria-label="打开菜单">☰</button><button class="brand" @click="navigate('home')">FanBBS</button><label class="search"><span>⌕</span><span class="sr-only">搜索社区</span><input v-model="query" placeholder="搜索帖子、用户或内容" @keyup.enter="runSearch"></label><div class="top-actions"><button class="icon-button" aria-label="发布" @click="openComposer">✎</button><button class="icon-button" aria-label="通知" @click="requireAuth(()=>navigate('messages'))">♢<i></i></button><button v-if="!viewer" class="text-button" @click="authMode='login';loginOpen=true">登录</button><button v-if="!viewer" class="primary small" @click="authMode='register';loginOpen=true">注册</button><button v-else class="user-chip" @click="navigate('me')">{{ viewer.name }}</button></div></header>
  <aside class="rail" aria-label="主导航"><nav><button :class="{active:view==='home'}" @click="navigate('home')"><b>⌂</b><span>首页</span></button><button :class="{active:view==='discover'}" @click="navigate('discover')"><b>◉</b><span>发现</span></button><button :class="{active:view==='shop'}" @click="loadShop"><b>◇</b><span>商城</span></button><button @click="changeTab('following');navigate('home')"><b>♙</b><span>关注</span></button><button :class="{active:view==='messages'}" @click="requireAuth(()=>navigate('messages'))"><b>▱</b><span>消息</span></button><button :class="{active:view==='saved'}" @click="requireAuth(()=>navigate('saved'))"><b>▯</b><span>收藏</span></button></nav><button class="rail-compose" aria-label="发布新帖" @click="openComposer">＋</button></aside>
  <main class="shell" id="feed">
    <section v-if="!detail&&view==='home'" class="timeline" aria-labelledby="feed-heading"><h1 id="feed-heading" class="sr-only">社区动态</h1>
      <section v-if="activeCategory" class="category-hero" :style="activeCategory.background_url?{backgroundImage:`linear-gradient(115deg,rgba(7,45,40,.9),rgba(7,45,40,.58)),url(${activeCategory.background_url})`}:{}"><img v-if="activeCategory.image_url" :src="activeCategory.image_url" :alt="`${activeCategory.name} 分类图标`"><div><span class="eyebrow">社区分类</span><h2>{{activeCategory.name}}</h2><p>{{activeCategory.description||'浏览这个分类里的社区动态。'}}</p><small>{{activeCategory.post_count||0}} 篇公开帖子</small></div><button class="category-follow" @click="toggleCategoryFollow(activeCategory)">{{activeCategory.followed?'★ 已关注':'☆ 关注分类'}}</button></section>
      <div v-if="!activeCategory&&homepage.announcements?.length" class="announcements"><a v-for="a in homepage.announcements.filter(x=>x.enabled)" :key="a.id" :href="a.link_url||'#'">{{a.text}}</a></div><div v-if="!activeCategory&&homepage.carousel?.some(x=>x.enabled)" class="home-carousel"><a v-for="slide in homepage.carousel.filter(x=>x.enabled)" :key="slide.id" :href="slide.link_url||'#'"><img v-if="slide.media_url" :src="slide.media_url" :alt="slide.title"><div><b>{{slide.title}}</b><p>{{slide.summary}}</p></div></a></div><div class="tabs" role="tablist" :aria-label="activeCategory?'分类动态排序':'动态类型'"><button v-for="t in activeCategory?categoryTabs:tabs" :key="t[0]" role="tab" :aria-selected="tab===t[0]" @click="activeCategory?changeCategoryTab(t[0]):changeTab(t[0])">{{t[1]}}</button></div>
      <div v-if="!viewer&&!activeCategory" class="join"><div><h2>加入对话</h2><p>登录后即可发帖、点赞、转发和回复。</p><button class="primary" @click="authMode='login';loginOpen=true">登录</button><button class="outline" @click="authMode='register';loginOpen=true">注册</button></div><div class="people" aria-hidden="true"><span>••</span><i></i><i></i><i></i></div></div>
      <p v-if="demoMode" class="notice" role="status">后端暂不可用，正在展示本地预览数据</p>
      <div v-if="status==='loading'" class="skeletons" aria-label="正在加载"><div v-for="n in 5" :key="n" class="skeleton"></div></div>
      <div v-else-if="status==='error'" class="empty" role="alert"><h2>动态加载失败</h2><p>{{error}}</p><button class="primary" @click="loadFeed">重试</button></div>
      <div v-else-if="status==='empty'" class="empty"><h2>{{activeCategory?`${activeCategory.name}还没有动态`:'这里还没有动态'}}</h2><p>成为第一个开启对话的人。</p><button class="primary" @click="openComposer">发布第一帖</button></div>
      <article v-for="p in visiblePosts" :key="p.id" class="post" @click.self="openDetail(p)"><div v-if="p.repostedBy" class="repost-label">↻ {{p.repostedBy}} 转发了</div><div class="avatar" aria-hidden="true">{{p.avatar||p.author.name[0]}}</div><div class="post-body"><header><button class="author" @click="openPublicProfile(p.author.id)">{{p.author.name}}</button><span>@{{p.author.handle}} · {{p.age}}</span><button class="more" aria-label="更多操作">⋮</button></header><button class="post-content" @click="openDetail(p)"><strong v-if="p.title" class="post-title">{{p.title}}</strong><span v-if="p.summary" class="post-summary">{{p.summary}}</span><span class="post-copy">{{p.content}}</span></button><div class="post-meta"><button v-if="p.category" class="meta-chip" @click="openCategory(p.category)">{{p.category.name}}</button><button v-for="tag in p.tags||[]" :key="tag.id" class="meta-chip" @click="openTag(tag)">#{{tag.name}}</button><span>{{p.visibility==='followers'?'仅关注者可见':'公开'}}</span></div><div v-if="Array.isArray(p.media)&&p.media.length" class="media-grid"><template v-for="m in p.media" :key="m.id"><video v-if="m.mime_type?.startsWith('video/')" :src="m.url" controls preload="metadata"></video><img v-else :src="m.url" :alt="m.alt_text||'帖子图片'" loading="lazy"></template></div><div v-else-if="p.media" class="media" role="img" :aria-label="p.mediaAlt"><span class="sun"></span><span class="skyline">▂▃▅▂▆▃▂</span><span class="river"></span></div><footer><button @click="openDetail(p)" :aria-label="`${p.comments} 条回复`">◯ <span>{{p.comments}}</span></button><button :class="{liked:p.reposted}" @click="repost(p)">↻ <span>{{p.reposts}}</span></button><button :class="{liked:p.liked}" @click="toggleLike(p)">♡ <span>{{p.likes}}</span></button><button :class="{liked:p.bookmarked}" @click="toggleBookmark(p)" aria-label="收藏">▯</button><span class="views">▥ {{p.views}}</span></footer></div></article>
      <button v-if="feedCursor&&!demoMode" class="outline load-more" :disabled="pageBusy" @click="loadMoreFeed">{{pageBusy?'加载中…':'加载更多动态'}}</button>
      <div v-if="status==='ready'&&!visiblePosts.length" class="empty"><h2>没有匹配的动态</h2><p>换一个关键词试试。</p><button class="outline" @click="query=''">清除搜索</button></div>
    </section>
    <section v-else-if="!detail&&view==='discover'" class="section-page"><h1>发现</h1><form class="discover-search" @submit.prevent="runSearch"><label for="discover-q">搜索社区</label><div><input id="discover-q" v-model="query" placeholder="帖子、用户或内容"><button class="primary">搜索</button></div></form><p v-if="sectionError" class="form-error" role="alert">{{sectionError}}</p><div class="chips category-grid" aria-label="分类"><article v-for="c in categories" :key="c.id" class="category-chip" :style="c.background_url?{backgroundImage:`linear-gradient(120deg,rgba(9,55,49,.88),rgba(9,55,49,.56)),url(${c.background_url})`}:{}"><button class="category-card-main" @click="openCategory(c)"><img v-if="c.image_url" :src="c.image_url" alt=""><span><b>{{c.name}}</b><small>{{c.description||`${c.post_count||0} 篇公开帖子`}}</small></span></button><button class="category-card-follow" :aria-label="`${c.followed?'取消关注':'关注'} ${c.name}`" @click="toggleCategoryFollow(c)">{{c.followed?'★':'☆'}}</button></article></div><h2 v-if="results.length">帖子</h2><article v-for="p in results" :key="p.id" class="compact-result"><button @click="openDetail(p)"><b>{{p.author.name}}</b><span>@{{p.author.handle}}</span><p>{{p.content}}</p></button><button class="outline" @click="toggleBookmark(p)">{{p.bookmarked?'取消收藏':'收藏'}}</button></article><h2 v-if="resultUsers.length">用户</h2><article v-for="u in resultUsers" :key="u.id" class="compact-result user-result"><div><b>{{u.display_name||u.name}}</b><span>@{{u.handle}}</span><p>{{u.bio}}</p></div><div class="user-result-actions"><button class="text-button" @click="messageUser(u)">私信</button><button class="outline" @click="toggleFollow(u)">{{u.following?'取消关注':'关注'}}</button></div></article><h2 v-if="resultTags.length">标签</h2><div class="chips"><button v-for="t in resultTags" :key="t.id" @click="query=t.name;runSearch()"># {{t.name}}</button></div><p v-if="!results.length&&!resultUsers.length&&!resultTags.length" class="empty-copy">输入关键词，发现帖子与社区成员。</p></section>
    <section v-else-if="!detail&&view==='saved'" class="section-page">
      <h1>我的收藏</h1><p v-if="sectionError" class="form-error">{{sectionError}}</p>
      <article v-for="p in bookmarks" :key="p.id" class="compact-result"><button @click="openDetail(p)"><b>{{p.author.name}}</b><p>{{p.content}}</p></button><button class="outline" @click="toggleBookmark(p)">取消收藏</button><button class="text-button" @click="addPostToCollection(p)">加入收藏集</button></article>
      <p v-if="!bookmarks.length" class="empty-copy">还没有收藏帖子。</p><button v-if="bookmarkCursor" class="outline load-more" :disabled="pageBusy" @click="loadMoreBookmarks">{{pageBusy?'加载中…':'加载更多收藏'}}</button>
      <section class="collection-panel"><h2>公开与私密收藏集</h2><p>书签始终私密；只有标为公开的收藏集会出现在个人主页。</p><form class="inline-form" @submit.prevent="createCollection"><input name="name" required maxlength="80" placeholder="收藏集名称"><input name="description" maxlength="500" placeholder="描述"><select name="visibility"><option value="private">私密</option><option value="public">公开</option></select><button class="primary">新建</button></form><article v-for="c in collections" :key="c.id" class="compact-result"><button @click="openCollection(c)"><b>{{c.name}}</b><p>{{c.description}}</p><span>{{c.visibility==='public'?'公开':'私密'}} · {{c.item_count}} 项</span></button><button class="danger-button" @click="removeCollection(c)">删除</button></article><article v-if="openedCollection" class="collection-detail"><button class="dialog-close" aria-label="关闭收藏集" @click="openedCollection=null">×</button><h3>{{openedCollection.collection.name}}</h3><article v-for="p in openedCollection.posts" :key="p.id" class="compact-result"><button @click="openDetail(p)"><b>{{p.title||p.content}}</b><span>@{{p.author.handle}}</span></button></article><p v-if="!openedCollection.posts.length">收藏集还没有内容。</p></article></section>
    </section>
    <section v-else-if="!detail&&view==='messages'" class="section-page"><div class="section-heading"><h1>消息</h1><div class="message-tabs"><button :class="{active:messageMode==='notifications'}" @click="messageMode='notifications';activeConversation=null">通知</button><button :class="{active:messageMode==='conversations'}" @click="loadConversations">私信</button></div><button v-if="messageMode==='notifications'" class="text-button" @click="markAllRead">全部已读</button></div><p v-if="sectionError" class="form-error">{{sectionError}}</p><template v-if="messageMode==='notifications'"><button v-for="n in notifications" :key="n.id" class="notification notification-action" :class="{unread:!n.read_at}" @click="openNotification(n)"><b>{{notificationTitle(n)}}</b><p>{{notificationDescription(n)}}</p><small v-if="n.subject_id" class="notification-subject">{{n.subject_type}} · {{n.subject_id}}</small><time>{{n.created_at}}</time></button><p v-if="!notifications.length" class="empty-copy">暂时没有新通知。</p><button v-if="notificationCursor" class="outline load-more" :disabled="pageBusy" @click="loadMoreNotifications">{{pageBusy?'加载中…':'加载更多通知'}}</button></template><template v-else-if="!activeConversation"><button v-for="c in conversations" :key="c.id" class="conversation-row" @click="openConversation(c)"><b>{{c.other_user?.display_name||c.title||'私信会话'}}</b><p>{{c.last_message?.content||'开始对话'}}</p><time>{{c.updated_at}}</time></button><p v-if="!conversations.length" class="empty-copy">还没有私信会话。</p><button v-if="conversationCursor" class="outline load-more" @click="loadMoreConversations">加载更多会话</button></template><template v-else><div class="conversation-heading"><button class="back" @click="activeConversation=null">← 返回会话</button><button class="text-button leave-conversation" @click="leaveConversation">离开会话</button></div><button v-if="messageCursor" class="text-button load-more" @click="loadOlderMessages">加载更早消息</button><div class="message-thread"><article v-for="m in messages" :key="m.id" class="message-bubble" :class="{mine:m.sender_id===viewer?.id}"><p>{{m.content}}</p><time>{{m.created_at}}<span v-if="messageReadLabel(m)" class="read-receipt"> · {{messageReadLabel(m)}}</span></time></article></div><form class="message-compose" @submit.prevent="sendMessage"><label class="sr-only" for="private-message">发送私信</label><input id="private-message" name="message" maxlength="2000" required placeholder="写一条消息…"><button class="primary" :disabled="busy">发送</button></form></template></section>
    <section v-else-if="!detail&&view==='me'" class="section-page"><div class="section-heading"><h1>个人资料</h1><button class="text-button" @click="logout">退出登录</button></div><p v-if="sectionError" class="form-error">{{sectionError}}</p><div class="profile-media-settings"><label class="avatar-upload">更新头像<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" @change="updateAvatar"></label><label class="avatar-upload">更新主页封面<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" @change="updateCover"></label></div><form class="profile-form" @submit.prevent="saveProfile"><label for="display-name">显示名称</label><input id="display-name" name="display_name" :value="viewer?.name" required maxlength="40"><label for="bio">简介</label><textarea id="bio" name="bio" :value="viewer?.bio" maxlength="240"></textarea><button class="primary" :disabled="busy">保存资料</button></form><section class="account-security"><h2>账号安全</h2><form class="security-form" @submit.prevent="changePassword"><label for="current-password">当前密码</label><input id="current-password" name="current_password" type="password" autocomplete="current-password" required><label for="account-new-password">新密码</label><input id="account-new-password" name="new_password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required><label for="confirm-new-password">再次输入新密码</label><input id="confirm-new-password" name="confirm_password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required><p v-if="accountError" class="form-error" role="alert">{{accountError}}</p><button class="primary" :disabled="accountBusy">{{accountBusy?'处理中…':'修改密码'}}</button></form><div class="danger-zone"><div><b>停用账号</b><p>停用后会退出登录并撤销全部设备会话。</p></div><button class="danger-button" :disabled="accountBusy" @click="deactivateAccount">停用账号</button></div></section><div class="profile-shortcuts"><button class="outline" @click="loadOrders">我的订单</button><button class="outline" @click="loadGamification">等级与积分</button><button class="outline" @click="loadShop">本地商城</button><button class="outline" @click="loadActivity">我的活动</button><button class="outline" @click="rotateCodes">更新恢复码</button></div><section v-if="activity.length" class="activity-list"><h2>我的活动</h2><article v-for="item in activity" :key="item.id||item.created_at"><b>{{item.type||item.action}}</b><p>{{item.summary||item.created_at}}</p></article></section><section class="privacy-lists"><h2>隐私与关注</h2><div class="privacy-grid"><section><h3>已屏蔽用户</h3><article v-for="u in blockedUsers" :key="u.id" class="compact-result"><div><b>{{u.display_name||u.name}}</b><span>@{{u.handle}}</span></div><button class="outline" @click="unblockUser(u)">解除屏蔽</button></article><p v-if="!blockedUsers.length" class="empty-inline">没有已屏蔽的用户。</p><button v-if="blockCursor" class="text-button load-more" @click="loadMoreBlocks">加载更多</button></section><section><h3>已关注分类</h3><article v-for="item in followedCategories" :key="(item.category||item).id" class="compact-result"><button @click="openCategory(item.category||item)"><b>{{(item.category||item).name}}</b><span>{{(item.category||item).post_count||0}} 篇帖子</span></button><button class="outline" @click="unfollowSavedCategory(item)">取消关注</button></article><p v-if="!followedCategories.length" class="empty-inline">还没有关注分类。</p><button v-if="categoryFollowCursor" class="text-button load-more" @click="loadMoreCategoryFollows">加载更多</button></section></div></section><section class="device-sessions"><h2>设备会话</h2><article v-for="session in deviceSessions" :key="session.id"><div><b>{{session.current?'当前设备':'其他设备'}}</b><p>创建于 {{session.created_at}}</p></div><button class="outline" @click="revokeDevice(session)">撤销</button></article></section><button v-if="viewer?.role==='moderator'||viewer?.role==='admin'" class="outline admin-link" @click="navigate('admin')">进入审核台</button></section>
    <section v-else-if="!detail&&view==='shop'" class="section-page shop-page">
      <div class="section-heading"><h1>本地商城</h1><button v-if="viewer" class="outline" @click="loadOrders">我的订单</button></div>
      <p class="notice">这里只创建不含付款的本地履约订单；支付、现金钱包、VIP 和外部物流均未启用。</p><p v-if="sectionError" class="form-error">{{sectionError}}</p>
      <div class="product-type-filter" role="group" aria-label="商品类型"><button :class="{active:!productTypeFilter}" @click="filterProducts('')">全部</button><button v-for="type in productTypes" :key="type.id" :class="{active:productTypeFilter===type.id}" @click="filterProducts(type.id)">{{type.name}}</button></div>
      <div class="product-grid"><article v-for="p in products" :key="p.id"><span class="eyebrow">{{p.type_name}}</span><h2>{{p.name}}</h2><p>{{p.description}}</p><span>编号 {{p.sku||'—'}} · 库存 {{p.inventory}}</span><div class="row-actions"><button class="outline" @click="openProduct(p)">查看详情</button><button class="primary" :disabled="p.inventory<1" @click="addCart(p)">加入清单</button></div></article></div><p v-if="!products.length" class="empty-copy">该类型暂时没有可用商品。</p>
      <article v-if="selectedProduct" class="product-detail" aria-live="polite"><button class="dialog-close" aria-label="关闭商品详情" @click="selectedProduct=null">×</button><span class="eyebrow">{{selectedProduct.type_name}} · {{selectedProduct.sku}}</span><h2>{{selectedProduct.name}}</h2><p>{{selectedProduct.description||'暂无商品说明。'}}</p><dl><div><dt>库存</dt><dd>{{selectedProduct.inventory}}</dd></div><div><dt>状态</dt><dd>{{selectedProduct.status}}</dd></div></dl><button class="primary" :disabled="selectedProduct.inventory<1" @click="addCart(selectedProduct)">加入清单</button></article>
      <aside v-if="viewer&&cart.length" class="cart-panel"><h2>履约清单</h2><div v-for="item in cart" :key="item.product.id" class="cart-row"><div><b>{{item.product.name}}</b><span>库存 {{item.product.inventory}}</span></div><div class="quantity-control" :aria-label="`${item.product.name} 数量`"><button :aria-label="`减少 ${item.product.name}`" @click="updateCartQuantity(item,-1)">−</button><output>{{item.quantity}}</output><button :aria-label="`增加 ${item.product.name}`" :disabled="item.quantity>=item.product.inventory||item.quantity>=100" @click="updateCartQuantity(item,1)">＋</button></div><button class="text-button remove-cart" @click="removeCartItem(item)">移除</button></div><button class="primary" @click="checkout">创建本地订单</button></aside>
    </section>
    <section v-else-if="!detail&&view==='orders'" class="section-page orders-page">
      <div class="section-heading"><h1>我的订单</h1><button class="outline" @click="loadShop">返回商城</button></div><p class="notice">订单不含付款承诺，只记录本地人工履约状态。</p><p v-if="sectionError" class="form-error">{{sectionError}}</p>
      <section class="shipping-panel"><h2>收货地址</h2><form class="address-form" @submit.prevent="saveShippingAddress"><input name="label" maxlength="40" placeholder="标签，如 家"><input name="recipient_name" required maxlength="80" placeholder="收件人"><input name="phone" required maxlength="40" placeholder="联系电话"><input name="region" required maxlength="120" placeholder="地区"><input name="address_line" required maxlength="300" placeholder="详细地址"><input name="postal_code" maxlength="20" placeholder="邮政编码"><label><input name="is_default" type="checkbox"> 设为默认</label><button class="primary">保存地址</button></form><article v-for="a in shippingAddresses" :key="a.id" class="address-row"><label><input v-model="selectedAddressId" type="radio" name="selected_address" :value="a.id"><b>{{a.label||a.recipient_name}}</b> {{a.recipient_name}} · {{a.region}} {{a.address_line}}<span v-if="a.is_default">（默认）</span></label><span class="row-actions"><button class="outline" @click="editShippingAddress(a)">编辑</button><button class="danger-button" @click="removeShippingAddress(a)">删除</button></span></article></section>
      <article v-for="o in orders" :key="o.id" class="order-row"><button class="order-summary" @click="openOrder(o)"><b>{{o.id}}</b><p>{{o.items.map(i=>`${i.name} × ${i.quantity}`).join('、')}}</p><span>{{o.status}} · {{o.created_at||'时间未提供'}} <template v-if="o.tracking_code">· {{o.fulfillment_carrier}} {{o.tracking_code}}</template></span></button><button v-if="o.status==='created'" class="outline" @click="cancelOrder(o)">取消</button></article><p v-if="!orders.length" class="empty-copy">还没有订单。</p>
      <article v-if="selectedOrder" class="order-detail"><button class="dialog-close" aria-label="关闭订单详情" @click="selectedOrder=null">×</button><h2>订单详情</h2><p><b>{{selectedOrder.id}}</b> · {{selectedOrder.status}}</p><ul><li v-for="item in selectedOrder.items" :key="item.product_id">{{item.name}}（{{item.sku}}）× {{item.quantity}}</li></ul><p v-if="selectedOrder.shipping_address">收货：{{selectedOrder.shipping_address.recipient_name}} · {{selectedOrder.shipping_address.region}} {{selectedOrder.shipping_address.address_line}}</p><ol v-if="selectedOrder.tracking_events?.length" class="tracking-list"><li v-for="event in selectedOrder.tracking_events" :key="event.id"><b>{{event.status}}</b> {{event.description}} <span>{{event.location}} · {{event.occurred_at}}</span></li></ol><p>创建：{{selectedOrder.created_at}}</p><p v-if="selectedOrder.fulfilled_at">完成：{{selectedOrder.fulfilled_at}}</p><p v-if="selectedOrder.cancelled_at">取消：{{selectedOrder.cancelled_at}}</p><p v-if="selectedOrder.tracking_code">履约记录：{{selectedOrder.fulfillment_carrier}} · {{selectedOrder.tracking_code}}</p><button v-if="selectedOrder.status==='created'" class="outline" @click="cancelOrder(selectedOrder)">取消订单</button></article>
    </section>
    <section v-else-if="!detail&&view==='gamification'" class="section-page gamification-page"><div class="section-heading"><h1>等级与积分</h1><button class="primary" @click="checkIn">今日签到</button></div><p class="notice">积分是社区内的非现金荣誉值，不能购买、兑换现金或转账。</p><p v-if="sectionError" class="form-error">{{sectionError}}</p><div v-if="game" class="game-summary"><div><b>Lv.{{game.level}} {{game.level_name}} · {{game.title}}</b><span>当前 {{game.points_balance}} 分 · 累计 {{game.lifetime_points}} 分</span></div><span>社区排名 {{game.rank}}</span></div><h2>任务</h2><article v-for="t in tasks" :key="t.id" class="task-row"><div><b>{{t.name}}</b><p>{{t.description||'由管理员验证完成情况。'}}</p><small>{{t.repeat_policy==='daily'?'每日任务':'一次性任务'}}<template v-if="t.reward_frame_id"> · 含头像框奖励</template></small></div><span :class="{claimed:t.claimed}">{{t.claimed?'本期已获奖':`${t.reward_points} 分`}}</span></article><p v-if="!tasks.length" class="empty-inline">暂时没有可参与的任务。</p><h2>头像框</h2><div class="frame-grid"><button v-for="f in frames" :key="f.id" :disabled="!f.entitled" :class="{selected:f.selected}" @click="chooseFrame(f)"><img v-if="f.image_url" :src="f.image_url" :alt="f.name"><span>{{f.name}}</span><small>{{f.selected?'使用中':f.entitled?'已获得':'未获得'}}</small></button></div><button v-if="frames.some(f=>f.selected)" class="text-button clear-frame" @click="clearFrame">清除当前头像框</button><p v-if="!frames.length" class="empty-inline">暂无头像框。</p><h2>排行榜</h2><ol class="rank-list"><li v-for="r in ranks" :key="r.user_id"><b>#{{r.rank}} {{r.display_name}}</b><span>Lv.{{r.level}} {{r.title}} · {{r.lifetime_points}} 分</span></li></ol><p v-if="!ranks.length" class="empty-inline">排行榜尚无数据。</p><h2>积分记录</h2><ol class="point-history"><li v-for="event in pointEvents" :key="event.id"><div><b>{{event.description}}</b><span>{{event.event_type}} · {{event.created_at}}</span></div><strong>+{{event.amount}}</strong></li></ol><p v-if="!pointEvents.length" class="empty-inline">还没有积分奖励记录。</p></section>
    <section v-else-if="!detail&&view==='profile'" class="section-page public-profile"><p v-if="sectionError" class="form-error">{{sectionError}}</p><template v-if="publicProfile"><div class="profile-cover" :style="publicProfile.cover_url?{backgroundImage:`url(${publicProfile.cover_url})`}:{}"></div><div class="profile-head"><div class="avatar">{{publicProfile.name?.[0]}}</div><div><h1>{{publicProfile.name}}</h1><p>@{{publicProfile.handle}}</p></div><div v-if="viewer?.id!==publicProfile.id" class="profile-actions"><button class="primary" @click="toggleFollow(publicProfile)">{{publicProfile.following?'取消关注':'关注'}}</button><button class="outline" @click="messageUser(publicProfile)">私信</button><button class="text-button" @click="toggleBlockProfile">{{publicProfile.blocked_by_me?'解除屏蔽':'屏蔽'}}</button><button class="text-button report-user" @click="reportUser(publicProfile)">举报</button></div></div><p>{{publicProfile.bio}}</p><div class="profile-counts"><button @click="loadSocial('followers')"><b>{{publicProfile.follower_count}}</b> 关注者</button><button @click="loadSocial('following')"><b>{{publicProfile.following_count}}</b> 正在关注</button><span><b>{{publicProfile.post_count}}</b> 帖子</span></div><div v-if="socialList.length" class="social-list"><article v-for="u in socialList" :key="u.id" class="compact-result"><button @click="openPublicProfile(u.id)"><b>{{u.display_name}}</b> @{{u.handle}}</button><button class="outline" @click="toggleFollow(u)">{{u.following?'取消关注':'关注'}}</button></article></div><div class="profile-content-tabs" role="tablist" aria-label="公开内容"><button role="tab" :aria-selected="publicContentTab==='posts'" @click="loadPublicContent('posts')">帖子</button><button role="tab" :aria-selected="publicContentTab==='comments'" @click="loadPublicContent('comments')">回复</button></div><template v-if="publicContentTab==='posts'"><article v-for="p in publicPosts" :key="p.id" class="compact-result profile-content-row"><button @click="openDetail(p)"><b>{{p.title||p.content||'帖子'}}</b><p v-if="p.title&&p.content">{{p.content}}</p><span>{{p.age}}</span></button></article><p v-if="!publicPosts.length" class="empty-inline">没有可见的帖子。</p></template><template v-else><article v-for="c in publicComments" :key="c.id" class="compact-result profile-content-row"><button @click="openProfileComment(c)"><p>{{c.content}}</p><span>{{c.age}}</span></button></article><p v-if="!publicComments.length" class="empty-inline">没有可见的回复。</p></template><button v-if="publicContentCursor" class="outline load-more" :disabled="pageBusy" @click="loadMorePublicContent">{{pageBusy?'加载中…':'加载更多'}}</button></template></section>
    <section v-else-if="!detail&&view==='admin'" class="section-page"><h1>社区管理</h1><p>服务端角色权限和不可变审计是所有管理操作的最终边界。</p><div class="admin-tabs"><button v-for="m in [['reports','举报'],['users','用户'],['content','内容'],['taxonomy','分类标签'],['commerce','商品订单'],['homepage','首页配置']]" :key="m[0]" :class="{active:adminMode===m[0]}" @click="m[0]==='homepage'?loadHomepageAdmin():loadAdmin(m[0])">{{m[1]}}</button></div><p v-if="sectionError" class="form-error">{{sectionError}}</p><template v-if="adminMode==='reports'"><article v-for="item in adminQueue" :key="item.id" class="review-item"><div><b>{{item.target_type}} · {{item.reason}}</b><p>{{item.status}} · {{item.target_id}}</p></div><button class="outline" @click="moderate(item,'dismiss')">驳回举报</button><button v-if="item.target_type==='post'||item.target_type==='comment'" class="primary" @click="moderate(item,'remove_content')">移除内容</button><button v-if="item.target_type==='user'&&viewer?.role==='admin'" class="primary" @click="moderate(item,'suspend_user')">停用用户</button></article><p v-if="!adminQueue.length" class="empty-copy">审核队列已清空。</p></template><template v-else-if="adminMode==='users'"><form class="admin-filters admin-user-filters" @submit.prevent="loadAdmin('users')"><input v-model="adminUserFilter.q" placeholder="搜索用户名、邮箱或昵称"><select v-model="adminUserFilter.status"><option value="">全部状态</option><option value="active">正常</option><option value="suspended">已停用</option></select><select v-model="adminUserFilter.role"><option value="">全部角色</option><option value="member">成员</option><option value="moderator">审核员</option><option value="admin">管理员</option></select><button class="outline">筛选</button></form><article v-for="u in adminUsers" :key="u.id" class="review-item"><div><b>{{u.display_name}} @{{u.handle}}</b><p>{{u.role}} · {{u.status}}</p></div><button class="outline" @click="changeUserStatus(u)">{{u.status==='active'?'停用':'恢复'}}</button></article></template><template v-else-if="adminMode==='content'"><form class="admin-filters" @submit.prevent="loadAdmin('content')"><input v-model="adminContentFilter.q" placeholder="搜索内容"><select v-model="adminContentFilter.status"><option value="published">已发布</option><option value="deleted">已删除</option><option value="draft">草稿</option></select><select v-model="adminContentFilter.type"><option value="">全部类型</option><option value="post">帖子</option><option value="comment">评论</option></select><button class="outline">筛选</button></form><article v-for="p in adminContent" :key="p.id" class="review-item"><div><b>{{p.title}}</b><p>{{p.author?.display_name}} · {{p.status}} · {{p.visibility}}</p></div><div class="admin-content-actions"><button class="outline" @click="openDetail(p)">查看</button><template v-if="p.moderation_state==='pending'"><button @click="decidePendingPost(p,'rejected')">拒绝</button><button class="primary" @click="decidePendingPost(p,'published')">发布</button></template><template v-else-if="p.status==='published'"><button @click="togglePostControl(p,'pinned')">{{p.pinned?'取消置顶':'置顶'}}</button><button @click="togglePostControl(p,'recommended')">{{p.recommended?'取消推荐':'推荐'}}</button></template></div></article></template><template v-else-if="adminMode==='taxonomy'"><div class="taxonomy-admin"><section class="category-admin-section"><div class="section-heading"><h2>分类展示</h2><button v-if="adminCategoryEditing" class="text-button" @click="resetAdminCategory">取消编辑</button></div><form class="category-admin-form" @submit.prevent="saveAdminCategory"><label>名称<input v-model.trim="adminCategoryForm.name" required maxlength="50"></label><label>Slug<input v-model.trim="adminCategoryForm.slug" required maxlength="50" pattern="[a-z0-9]+(?:-[a-z0-9]+)*"></label><label class="category-description-field">描述<textarea v-model.trim="adminCategoryForm.description" maxlength="500"></textarea></label><label>图标或图片 URL<input v-model.trim="adminCategoryForm.image_url" maxlength="500" placeholder="/media/category-icon.webp"></label><label>背景图片 URL<input v-model.trim="adminCategoryForm.background_url" maxlength="500" placeholder="https://… 或站内路径"></label><button class="primary">{{adminCategoryEditing?'保存分类':'新建分类'}}</button></form><article v-for="c in adminTaxonomy.categories" :key="c.id" class="taxonomy-row rich-taxonomy-row"><img v-if="c.image_url" :src="c.image_url" alt=""><span><b>{{c.name}}</b><small>{{c.slug}}<template v-if="c.description"> · {{c.description}}</template></small></span><span><button @click="editAdminCategory(c)">编辑</button><button @click="removeTaxonomy('category',c)">删除</button></span></article></section><section><div class="section-heading"><h2>标签</h2><button class="outline" @click="createTaxonomy('tag')">新建</button></div><div v-for="t in adminTaxonomy.tags" :key="t.id" class="taxonomy-row"><span>{{t.name}} · {{t.slug}}</span><span><button @click="editTaxonomy('tag',t)">编辑</button><button @click="removeTaxonomy('tag',t)">删除</button></span></div></section></div></template><template v-else-if="adminMode==='commerce'">
      <div class="commerce-admin">
        <section class="admin-commerce-section"><div class="section-heading"><h2>商品类型</h2><button v-if="adminTypeEditing" class="text-button" @click="resetAdminType">取消编辑</button></div><form class="admin-inline-form" @submit.prevent="saveAdminType"><input v-model.trim="adminTypeForm.name" aria-label="类型名称" placeholder="类型名称" required maxlength="80"><input v-model.trim="adminTypeForm.slug" aria-label="类型标识" placeholder="英文 slug" required pattern="[a-z0-9]+(?:[-_][a-z0-9]+)*"><select v-model="adminTypeForm.status" aria-label="类型状态"><option value="active">启用</option><option value="archived">归档</option></select><input v-model.trim="adminTypeForm.reason" aria-label="类型变更理由" placeholder="审计理由"><button class="primary">{{adminTypeEditing?'保存类型':'新建类型'}}</button></form><article v-for="type in adminCommerce.types" :key="type.id" class="admin-commerce-row"><div><b>{{type.name}}</b><span>{{type.slug}} · {{type.status}}</span></div><div class="row-actions"><button class="outline" @click="editAdminType(type)">编辑</button><button class="danger-button" @click="removeAdminType(type)">删除</button></div></article>
        </section>
        <section class="admin-commerce-section"><div class="section-heading"><h2>商品</h2><button v-if="adminProductEditing" class="text-button" @click="resetAdminProduct">取消编辑</button></div><form class="admin-product-form" @submit.prevent="saveAdminProduct"><select v-model="adminProductForm.type_id" aria-label="商品类型" required><option disabled value="">选择类型</option><option v-for="type in adminCommerce.types" :key="type.id" :value="type.id">{{type.name}}</option></select><input v-model.trim="adminProductForm.name" aria-label="商品名称" placeholder="商品名称" required maxlength="120"><input v-model.trim="adminProductForm.sku" aria-label="商品编号" placeholder="SKU" required pattern="[a-z0-9]+(?:[-_][a-z0-9]+)*"><input v-model.number="adminProductForm.inventory" aria-label="商品库存" type="number" min="0" max="1000000" required><select v-model="adminProductForm.status" aria-label="商品状态"><option value="draft">草稿</option><option value="active">启用</option><option value="archived">归档</option></select><textarea v-model.trim="adminProductForm.description" aria-label="商品说明" placeholder="商品说明" maxlength="2000"></textarea><input v-model.trim="adminProductForm.reason" aria-label="商品变更理由" placeholder="审计理由"><button class="primary">{{adminProductEditing?'保存商品':'新建商品'}}</button></form><article v-for="product in adminCommerce.products" :key="product.id" class="admin-commerce-row"><div><b>{{product.name}}</b><span>{{product.sku}} · {{product.type_name}} · 库存 {{product.inventory}} · {{product.status}}</span></div><div class="row-actions"><button class="outline" @click="editAdminProduct(product)">编辑</button><button class="danger-button" @click="removeAdminProduct(product)">删除</button></div></article>
        </section>
        <section class="admin-commerce-section admin-orders"><div class="section-heading"><h2>本地订单</h2><form @submit.prevent="loadAdmin('commerce')"><select v-model="adminOrderFilter" aria-label="订单状态筛选"><option value="">全部状态</option><option value="created">待处理</option><option value="cancelled">已取消</option><option value="fulfilled">已手工履约</option></select><button class="outline">筛选</button></form></div><p class="notice">状态更新仅写入本地人工履约记录，不会联系支付或物流服务。</p><article v-for="order in adminCommerce.orders" :key="order.id" class="admin-commerce-row"><button class="order-summary" @click="openAdminOrder(order)"><b>{{order.id}}</b><span>{{order.user_id}} · {{order.status}} · {{order.items.map(item=>`${item.name} × ${item.quantity}`).join('、')}}</span></button><div v-if="order.status==='created'" class="row-actions"><button class="outline" @click="transitionAdminOrder(order,'cancelled')">管理员取消</button><button class="primary" @click="transitionAdminOrder(order,'fulfilled')">记录手工履约</button></div></article><article v-if="selectedAdminOrder" class="order-detail"><button class="dialog-close" aria-label="关闭订单详情" @click="selectedAdminOrder=null">×</button><h3>订单 {{selectedAdminOrder.id}}</h3><p>{{selectedAdminOrder.status}} · 用户 {{selectedAdminOrder.user_id}}</p><ul><li v-for="item in selectedAdminOrder.items" :key="item.product_id">{{item.name}}（{{item.sku}}）× {{item.quantity}}</li></ul><p v-if="selectedAdminOrder.tracking_code">履约记录：{{selectedAdminOrder.fulfillment_carrier}} · {{selectedAdminOrder.tracking_code}}</p><ol v-if="selectedAdminOrder.tracking_events?.length" class="tracking-list"><li v-for="event in selectedAdminOrder.tracking_events" :key="event.id"><b>{{event.status}}</b> {{event.description}} <span>{{event.location}} · {{event.occurred_at}}</span></li></ol><button v-if="selectedAdminOrder.status==='fulfilled'" class="outline append-tracking" @click="appendTrackingEvent(selectedAdminOrder)">追加手工物流事件</button></article></section>
      </div>
    </template><template v-else-if="adminMode==='homepage'"><form v-if="homepageAdmin" class="homepage-editor" @submit.prevent="saveHomepage"><label>状态<select name="status" :value="homepageAdmin.status"><option value="draft">草稿</option><option value="published">发布</option></select></label><label>首页 JSON<textarea name="payload" :value="JSON.stringify(homepageAdmin.payload,null,2)" spellcheck="false"></textarea></label><p>版本 {{homepageAdmin.version}} · 保存使用 If-Match 防止覆盖其他管理员修改</p><button class="primary">保存首页配置</button></form></template></section>
    <section v-else class="detail"><button class="back" @click="closeDetail">← 返回</button><button class="report-button" @click="reportPost(detail)">举报</button><h1 tabindex="-1" class="detail-title">{{detail.title||'帖子详情'}}</h1><p v-if="detail.summary" class="detail-summary">{{detail.summary}}</p><div v-if="viewer?.id===detail.author.id" class="owner-actions"><button class="outline" @click="editPost(detail)">编辑</button><button class="outline" @click="showRevisions(detail)">修订历史</button><button class="danger-button" @click="deletePost(detail)">删除</button></div><article class="post detail-post"><div class="avatar">{{detail.avatar}}</div><div class="post-body"><header><button class="author" @click="openPublicProfile(detail.author.id)">{{detail.author.name}}</button><span>@{{detail.author.handle}} · {{detail.age}}</span></header><div class="post-meta"><button v-if="detail.category" class="meta-chip" @click="openCategory(detail.category)">{{detail.category.name}}</button><button v-for="tag in detail.tags||[]" :key="tag.id" class="meta-chip" @click="openTag(tag)">#{{tag.name}}</button><span>{{detail.visibility==='followers'?'仅关注者可见':'公开'}}</span></div><p class="detail-copy">{{detail.content}}</p><div v-if="Array.isArray(detail.media)&&detail.media.length" class="media-grid"><template v-for="m in detail.media" :key="m.id"><video v-if="m.mime_type?.startsWith('video/')" :src="m.url" controls preload="metadata"></video><img v-else :src="m.url" :alt="m.alt_text||'帖子图片'" loading="lazy"></template></div><footer><button>◯ {{detail.comments}}</button><button :class="{liked:detail.reposted}" @click="repost(detail)">↻ {{detail.reposts}}</button><button :class="{liked:detail.liked}" @click="toggleLike(detail)">♡ {{detail.likes}}</button><button :class="{liked:detail.bookmarked}" @click="toggleBookmark(detail)" aria-label="收藏">▯</button></footer></div></article><section v-if="postRevisions.length" class="revision-list"><h2>修订历史</h2><article v-for="r in postRevisions" :key="r.version"><div><b>版本 {{r.version}}</b><time>{{r.created_at}}</time></div><h3>{{r.title}}</h3><p v-if="r.summary">{{r.summary}}</p><p>{{r.body}}</p><small>{{r.visibility==='followers'?'仅关注者可见':'公开'}}<template v-if="r.category_id"> · 分类 {{r.category_id}}</template><template v-if="r.tag_ids?.length"> · 标签 {{r.tag_ids.join('、')}}</template></small></article></section><section class="comments"><h2>回复</h2><form v-if="viewer" @submit.prevent="submitComment"><label for="comment">加入对话</label><textarea id="comment" name="comment" required maxlength="1000" placeholder="写下你的回复…"></textarea><button class="primary" :disabled="busy">回复</button></form><button v-else class="outline login-reply" @click="loginOpen=true">登录后回复</button><article v-for="c in comments" :key="c.id" class="comment" :style="{'--depth':Math.min(c.depth||0,2)}" :data-depth="c.depth||0"><div class="avatar">{{c.author.name[0]}}</div><div><b>{{c.author.name}}</b> <span>@{{c.author.handle}} · {{c.age}}</span><p>{{c.content}}</p><div class="comment-actions"><button :class="{liked:c.liked}" @click="toggleCommentLike(c)">♡ {{c.like_count||0}}</button><button v-if="(c.depth||0)<2" @click="startReply(c)">回复</button><button v-if="viewer?.id!==c.author.id" @click="reportComment(c)">举报</button><template v-if="viewer?.id===c.author.id"><button @click="editComment(c)">编辑</button><button @click="deleteComment(c)">删除</button></template></div><form v-if="replyingTo?.id===c.id" class="inline-reply" @submit.prevent="submitReply(c,$event)"><label :for="`reply-${c.id}`">回复 {{c.author.name}}</label><textarea :id="`reply-${c.id}`" name="reply" required maxlength="2000" :placeholder="`回复 @${c.author.handle}`"></textarea><div><button type="button" class="text-button" @click="replyingTo=null">取消</button><button class="primary" :disabled="busy">发布回复</button></div></form></div></article><p v-if="!comments.length">还没有回复。</p><button v-if="commentCursor" class="outline load-more" :disabled="pageBusy" @click="loadMoreComments">{{pageBusy?'加载中…':'加载更多回复'}}</button></section></section>
  </main>
  <aside v-if="view==='profile'&&publicCollections.length&&!detail" class="public-collections" aria-label="公开收藏集"><h2>公开收藏集</h2><button v-for="c in publicCollections" :key="c.id" @click="openCollection(c)"><b>{{c.name}}</b><span>{{c.description||'查看公开内容'}}</span></button></aside>
  <div v-if="openedCollection" class="backdrop" @mousedown.self="openedCollection=null"><section class="dialog collection-dialog" role="dialog" aria-modal="true" aria-labelledby="collection-title"><button class="dialog-close" aria-label="关闭收藏集" @click="openedCollection=null">×</button><h2 id="collection-title">{{openedCollection.collection.name}}</h2><p>{{openedCollection.collection.description}}</p><article v-for="p in openedCollection.posts" :key="p.id" class="compact-result"><button @click="openedCollection=null;openDetail(p)"><b>{{p.title||p.content}}</b><span>@{{p.author.handle}}</span></button></article><p v-if="!openedCollection.posts.length">收藏集还没有可见内容。</p></section></div>
  <button class="mobile-fab" aria-label="发布新帖" @click="openComposer">＋<small>发布</small></button>
  <nav class="bottom-nav" aria-label="移动端主导航"><button :class="{active:view==='home'}" @click="navigate('home')"><b>⌂</b><span>首页</span></button><button :class="{active:view==='discover'}" @click="navigate('discover')"><b>◉</b><span>发现</span></button><button :class="{active:view==='messages'}" @click="requireAuth(()=>navigate('messages'))"><b>▱</b><span>消息</span></button><button :class="{active:view==='me'}" @click="requireAuth(()=>navigate('me'))"><b>♙</b><span>我的</span></button></nav>

  <div v-if="loginOpen" class="backdrop" @mousedown.self="closeDialog('login')"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="login-title"><button class="dialog-close" aria-label="关闭" @click="closeDialog('login')">×</button><h2 id="login-title">{{authMode==='login'?'欢迎回来':authMode==='register'?'创建账号':authMode==='recover'?'恢复账号':'保存恢复码'}}</h2><p>{{authMode==='login'?'登录后加入 FanBBS 的每一次对话':authMode==='register'?'用本地账号加入社区':authMode==='recover'?'使用注册或上次恢复时保存的一次性恢复码':'恢复码只显示这一次，请离线安全保存'}}</p><form v-if="authMode==='login'" @submit.prevent="doLogin"><label for="identity">用户名或邮箱</label><input id="identity" name="identity" autocomplete="username" required><label for="password">密码</label><input id="password" name="password" type="password" autocomplete="current-password" required><p v-if="loginError" class="form-error" role="alert">{{loginError}}</p><button class="primary wide" :disabled="busy">{{busy?'正在登录…':'登录'}}</button><button type="button" class="text-button" @click="authMode='register';loginError=''">还没有账号？注册</button><button type="button" class="text-button" @click="authMode='recover';loginError=''">忘记密码？使用恢复码</button></form><form v-else-if="authMode==='register'" @submit.prevent="doRegister"><label for="new-handle">用户名</label><input id="new-handle" name="handle" autocomplete="username" minlength="3" maxlength="24" required><label for="new-email">邮箱</label><input id="new-email" name="email" type="email" autocomplete="email" required><label for="new-name">显示名称</label><input id="new-name" name="display_name" maxlength="40" required><label for="new-password">密码</label><input id="new-password" name="password" type="password" autocomplete="new-password" minlength="8" required><p v-if="loginError" class="form-error" role="alert">{{loginError}}</p><button class="primary wide" :disabled="busy">{{busy?'正在创建…':'注册'}}</button><button type="button" class="text-button" @click="authMode='login';loginError=''">已有账号？登录</button></form><form v-else-if="authMode==='recover'" @submit.prevent="doRecover"><label for="recover-account">用户名或邮箱</label><input id="recover-account" name="account" required><label for="recover-code">一次性恢复码</label><input id="recover-code" name="recovery_code" required><label for="recover-password">新密码</label><input id="recover-password" name="new_password" type="password" minlength="8" required><p v-if="loginError" class="form-error">{{loginError}}</p><button class="primary wide" :disabled="busy">重置密码</button></form><div v-else class="recovery-codes"><ul><li v-for="code in recoveryCodes" :key="code"><code>{{code}}</code></li></ul><button class="primary wide" @click="finishRecoveryCodes">我已安全保存</button></div></section></div>
  <div v-if="composerOpen" class="backdrop" @mousedown.self="closeDialog('compose')"><section class="dialog composer" role="dialog" aria-modal="true" aria-labelledby="compose-title"><button class="dialog-close" aria-label="关闭" @click="closeDialog('compose')">×</button><h2 id="compose-title">发布新帖</h2><form class="composer-form" @submit.prevent="publish"><label for="compose-title-field">标题（可选）</label><input id="compose-title-field" v-model="composeFields.title" minlength="3" maxlength="120" placeholder="3–120 个字"><label for="compose-summary">摘要（可选）</label><textarea id="compose-summary" v-model="composeFields.summary" maxlength="500" placeholder="用一句话介绍内容"></textarea><label for="draft">正文</label><textarea id="draft" v-model="draft" maxlength="50000" required @input="saveDraft" autofocus></textarea><div class="compose-grid"><label for="compose-kind">内容类型<select id="compose-kind" v-model="composeFields.kind"><option value="article">文章</option><option value="image">图片</option><option value="video">视频</option></select></label><label for="compose-category">分类<select id="compose-category" v-model="composeFields.categoryId"><option value="">不选择</option><option v-for="category in composerCategories" :key="category.id" :value="category.id">{{category.name}}</option></select></label><label for="compose-visibility">可见范围<select id="compose-visibility" v-model="composeFields.visibility"><option value="public">所有人可见</option><option value="followers">仅关注者可见</option></select></label></div><fieldset v-if="composerTags.length" class="tag-picker"><legend>标签（最多 10 个）</legend><label v-for="tag in composerTags" :key="tag.id"><input v-model="composeFields.tagIds" type="checkbox" :value="tag.id" :disabled="!composeFields.tagIds.includes(tag.id)&&composeFields.tagIds.length>=10"># {{tag.name}}</label></fieldset><label class="media-picker">添加图片或视频（最多 8 个）<input type="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4" multiple @change="selectMedia"></label><ul v-if="selectedFiles.length" class="selected-media"><li v-for="file in selectedFiles" :key="file.name">{{file.name}}</li></ul><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="compose-actions"><span>{{draft.length}} / 50000 · 草稿自动保存</span><button class="primary" :disabled="busy||!draft.trim()">{{busy?'发布中…':'发布'}}</button></div></form></section></div>
  <div v-if="postEditor" class="backdrop" @mousedown.self="postEditor=null"><section class="dialog composer post-editor" role="dialog" aria-modal="true" aria-labelledby="edit-post-title"><button class="dialog-close" aria-label="关闭编辑" @click="postEditor=null">×</button><h2 id="edit-post-title">编辑帖子</h2><form class="composer-form" @submit.prevent="savePostEdit"><label for="edit-post-title-field">标题</label><input id="edit-post-title-field" v-model.trim="postEditFields.title" required minlength="3" maxlength="120"><label for="edit-post-summary">摘要</label><textarea id="edit-post-summary" v-model="postEditFields.summary" maxlength="500"></textarea><label for="edit-post-content">正文</label><textarea id="edit-post-content" v-model="postEditFields.content" required maxlength="50000"></textarea><div class="compose-grid edit-post-grid"><label for="edit-post-category">分类<select id="edit-post-category" v-model="postEditFields.categoryId"><option value="">不选择</option><option v-for="category in composerCategories" :key="category.id" :value="category.id">{{category.name}}</option></select></label><label for="edit-post-visibility">可见范围<select id="edit-post-visibility" v-model="postEditFields.visibility"><option value="public">所有人可见</option><option value="followers">仅关注者可见</option></select></label></div><fieldset v-if="composerTags.length" class="tag-picker"><legend>标签（最多 10 个）</legend><label v-for="tag in composerTags" :key="tag.id"><input v-model="postEditFields.tagIds" type="checkbox" :value="tag.id" :disabled="!postEditFields.tagIds.includes(tag.id)&&postEditFields.tagIds.length>=10"># {{tag.name}}</label></fieldset><div class="compose-actions"><span>{{postEditFields.content.length}} / 50000</span><div><button type="button" class="text-button" @click="postEditor=null">取消</button><button class="primary" :disabled="busy||!postEditFields.content.trim()">{{busy?'保存中…':'保存修改'}}</button></div></div></form></section></div>
  <div class="toast" aria-live="polite">{{toast}}</div>
</template>
